        sidebar_outer = tk.Frame(main, bg='#161b22', width=285, relief='flat')
        sidebar_outer.pack(side='left', fill='y', padx=(0, 8))
        sidebar_outer.pack_propagate(False)

        # The selector list can grow beyond a laptop-height window.  Keep the
        # period/summary area fixed while making just this long control area
        # vertically scrollable.
        selector_scroll = tk.Frame(sidebar_outer, bg='#161b22')
        selector_scroll.pack(fill='both', expand=True, side='top')
        selector_canvas = tk.Canvas(selector_scroll, bg='#161b22',
                                    highlightthickness=0, bd=0)
        selector_bar = ttk.Scrollbar(selector_scroll, orient='vertical',
                                     command=selector_canvas.yview)
        selector_canvas.configure(yscrollcommand=selector_bar.set)
        selector_bar.pack(side='right', fill='y', padx=(0, 2), pady=4)
        selector_canvas.pack(side='left', fill='both', expand=True)

        top_block = tk.Frame(selector_canvas, bg='#161b22')
        selector_window = selector_canvas.create_window((0, 0), window=top_block,
                                                        anchor='nw')

        def _resize_selector_scroll(event=None):
            selector_canvas.configure(scrollregion=selector_canvas.bbox('all'))

        def _fit_selector_width(event):
            selector_canvas.itemconfigure(selector_window, width=event.width)

        top_block.bind('<Configure>', _resize_selector_scroll)
        selector_canvas.bind('<Configure>', _fit_selector_width)

        # Dragging/clicking the scrollbar always works.  Mouse-wheel support
        # is deliberately scoped to this canvas so it does not steal scrolling
        # from SCA or other pop-up windows.
        selector_canvas.bind('<MouseWheel>',
            lambda e: selector_canvas.yview_scroll(int(-e.delta / 120), 'units'))

        tk.Label(top_block, text="Indices", bg='#161b22', fg='#cdd9e5',
                 font=('Segoe UI', 11, 'bold')).pack(anchor='w', padx=10, pady=(10, 4))

        # ── Live description panel — updates on hover over any ⓘ next to an
        # index checkbox, so a user can see what a series actually means
        # before ticking it on. Placed once here; every checkbox row below
        # just points its hover handler at this same StringVar/label.
        self._index_guide_var = tk.StringVar(value='ⓘ Hover an index for a description.')
        self._index_guide_lbl = tk.Label(
            top_block, textvariable=self._index_guide_var, bg='#0d1117',
            fg='#00C9FF', font=('Segoe UI', 7), wraplength=250, justify='left',
            anchor='w', height=3)
        self._index_guide_lbl.pack(fill='x', padx=10, pady=(0, 6))

        self._accordion_open = {}

        def _make_section(parent, title, labels, accent='#555'):
            self._accordion_open[title] = tk.BooleanVar(value=True)
            hdr = tk.Frame(parent, bg='#1e252d', cursor='hand2')
            hdr.pack(fill='x', padx=4, pady=(3, 0))
            arrow_var = tk.StringVar(value='▾')
            tk.Label(hdr, textvariable=arrow_var,
                     bg='#1e252d', fg=accent,
                     font=('Segoe UI', 8)).pack(side='left', padx=(6, 2))
            tk.Label(hdr, text=title, bg='#1e252d', fg=accent,
                     font=('Segoe UI', 8, 'bold')).pack(side='left')
            body = tk.Frame(parent, bg='#161b22')
            body.pack(fill='x', padx=4)
            for lbl in labels:
                self._make_checkbox(body, lbl)
            def _toggle(event=None, av=arrow_var, t=title, b=body, p=parent):
                if self._accordion_open[t].get():
                    b.pack_forget()
                    av.set('▸')
                    self._accordion_open[t].set(False)
                else:
                    b.pack(fill='x', padx=4)
                    av.set('▾')
                    self._accordion_open[t].set(True)
