        _make_section(top_block, 'Thematic',
                      [CHAMPIONS_LABEL, KINGS10_LABEL, GEM20_LABEL, DIVA20_LABEL, BBI30_LABEL], accent='#FF6EC7')

        # ── World (Performance) — history is fetched on demand ────────────────
