    # ── MYFOLIO launcher ──────────────────────────────────────────────────────
    def _open_myfolio(self):
        """MYFOLIO is now merged into SCA Tracker for a unified portfolio view."""
        self._open_sca()

    def _open_lottostock(self):
        """Open LottoStock, linked live to this K-ID's SWAY1-MYR holdings."""
        has_src = sca_has_source(load_app_settings())
        LottoStockWindow(self,
                          preloaded_rows=self.newpor_rows if has_src else None,
                          preloaded_portfolios=self.newpor_portfolios if has_src else None,
                          preloaded_validation=self.newpor_validation if has_src else None)

    def _open_sca(self):
        """Open the SCA · NEWPOR TRACKER portfolio dashboard.
        The splash preloads the ledger before we know whose K-ID is active, so
        only hand that preload over once the user has confirmed their source —
        otherwise SCA would render demo rows under their name."""
        has_src = sca_has_source(load_app_settings())
        opie_result = self._opie_before_module('sca',
            self.newpor_portfolios if has_src else None)
        self._sca_win = SCAWindow(self,
                  preloaded_rows=self.newpor_rows if has_src else None,
                  preloaded_portfolios=self.newpor_portfolios if has_src else None,
                  opie_context=opie_result)

    def _opie_before_module(self, module: str, portfolios=None) -> dict:
        """Run a fail-safe OPIE pre-processing pass before a module opens."""
        if self.opie is None:
            return {"status": "unavailable", "message": "OPIE is not initialised."}
        try:
            return self.opie.before_module(module, portfolios=portfolios,
                                           wallet=self._pts_load())
        except Exception as exc:
            # OPIE advises; it must never prevent an established workflow from opening.
            return {"status": "unavailable", "message": f"OPIE unavailable: {exc}"}

    def _opie_dash_chat_submit(self, entry_widget):
        """Dashboard-level twin of SCA's OPIE chat trigger — same 'Hi, Opie'
        greeting, reachable without opening SCA first."""
        text = entry_widget.get().strip()
        if not text or text == 'Type: Hi, Opie':
            return
        greeting = text.lower().replace(',', '').replace('!', '').strip()
        if greeting in _OPIE_GREETINGS:
            self._opie_dash_reply_var.set(self._opie_dash_summary())
        else:
            self._opie_dash_reply_var.set('Try: "Hi, Opie" for a quick portfolio summary.')
        self._opie_dash_reply_row.pack(fill='x', pady=(0, 4))
        entry_widget.delete(0, 'end')
        self.focus_set()

    def _opie_open_popup(self):
        """Click/Enter on the 🤖 trigger — pop up the OPIE chat window (or
        just focus it if one's already open). The window itself stays idle
        until the user types 'Hi, Opie'."""
        sca = getattr(self, '_sca_win', None)
        host = sca if (sca is not None and getattr(sca, '_portfolios', None)) else self
        _opie_open_chat(self, host, CURRENT_KID)

    def _opie_dash_summary(self) -> str:
        """Prefer SCA's live, FX-forced figures if that window is open with
        prices loaded; otherwise fall back to a cost-basis-only summary from
        whatever's preloaded on the dashboard (no live prices/FX at this
        point unless SCA has already fetched them)."""
        sca = getattr(self, '_sca_win', None)
        if sca is not None and getattr(sca, '_portfolios', None):
            try:
                return sca._opie_lightweight_summary()
            except Exception:
                pass

        portfolios = self.newpor_portfolios
        if not portfolios:
            return "Hi! No portfolio loaded yet — open SCA to connect a source."

        positions, cost_total = 0, 0.0
        ccy_counts = {}
        for port in portfolios.values():
            c = port.get('base_currency', 'USD')
            ccy_counts[c] = ccy_counts.get(c, 0) + 1
            for ticker, item in port.get('holdings', {}).items():
                if item.get('_is_cash'):
                    continue
                shares = item.get('shares', 0)
                if not shares or shares <= 0:
                    continue
                positions  += 1
                cost_total += item.get('cost_value', 0.0)   # not FX-forced yet — no prices loaded here

        base_ccy = get_home_currency() if ccy_counts else 'MYR'
        prefix = ccy_symbol(base_ccy)
        diversification = ('not available' if not positions else
                            'concentrated' if positions < 4 else
                            'developing' if positions < 8 else 'diversified')
        return (f"{positions} active position(s), diversification is {diversification}. "
                f"Cost basis: {prefix}{cost_total:,.2f} "
                f"(open SCA for live value, return % and FX-forced totals).")

    def _dev_quick_switch(self, win=None):
        """🔁 Quick-switch between admin1 and test1 only — both reserved as
        the developer's own accounts, so this skips the PIN screen entirely
        and reloads straight into the other one. Auto-creates test1 (PIN
        0000) the first time if it doesn't exist yet."""
        cur = (CURRENT_KID or '').strip().lower()
        if cur not in (ADMIN_KID, TEST_KID):
            return
        target = TEST_KID if cur == ADMIN_KID else ADMIN_KID
        if not messagebox.askyesno('Quick Switch',
                f'Switch to {target} for testing?\n\n'
                f'admin1 and test1 are both your own reserved dev/test '
                f'accounts — this skips the PIN screen and reloads the app '
                f'straight into {target}.', parent=(win or self)):
            return
        # Flush THIS K-ID's wallet to disk before tearing the window down —
        # every credit mutation already saves immediately via _pts_save, but
        # this guarantees a final round-trip so nothing pending is lost when
        # we destroy(). Always re-load fresh right before writing, so we
        # never save over any other data written elsewhere in the meantime.
        self._pts_save(self._pts_load())
        s = load_app_settings()
        if target == TEST_KID and not kid_find_account(s, TEST_KID):
            kid_create(s, TEST_KID, '0000')
            save_app_settings(s)
        if win is not None:
            win.destroy()
        self.destroy()
        lock = AppLockScreen()
        lock._launch(target)

    def _open_settings(self):
        """Settings — K-ID account, cache management."""
        win = tk.Toplevel(self)
        win.title("Settings")
        win.configure(bg='#0d1117')
        win.geometry("440x480")
        win.resizable(False, False)
        win.transient(self)
        win.grab_set()

        tk.Label(win, text="⚙ SETTINGS", font=("Segoe UI", 13, "bold"),
                 fg='#cdd9e5', bg='#0d1117').pack(pady=(18, 10))

        settings = load_app_settings()

        # ── K-ID account ──────────────────────────────────────────────────────
        box = tk.Frame(win, bg='#161b22', highlightbackground='#30363D',
                       highlightthickness=1, padx=16, pady=12)
        box.pack(fill='x', padx=20)
        tk.Label(box, text="🆔  K-ID ACCOUNT", font=("Segoe UI", 9, "bold"),
                 fg='#58A6FF', bg='#161b22').pack(anchor='w')

        acc = kid_find_account(settings, CURRENT_KID) if CURRENT_KID else None
        who = CURRENT_KID or 'guest (no account)'
        tk.Label(box, text=f"Signed in as:  {who}",
                 font=("Segoe UI", 10, "bold"), fg='#cdd9e5',
                 bg='#161b22').pack(anchor='w', pady=(6, 0))
        if acc:
            tk.Label(box, text=f"K-ID created {acc.get('created', '—')}",
                     font=("Segoe UI", 7), fg='#555', bg='#161b22').pack(anchor='w')

        n_acc = len(settings.get('kid_accounts', []))
        tk.Label(box,
                 text=f"{n_acc} K-ID{'s' if n_acc != 1 else ''} on this device. "
                      f"Each has its own portfolio, PTS wallet and warrant book.",
                 font=("Segoe UI", 8), fg='#888', bg='#161b22',
                 wraplength=380, justify='left').pack(anchor='w', pady=(6, 0))

        # ── Dev quick-switch — admin1 ⇄ test1 only. Both are reserved as the
        # developer's own accounts, so this skips the PIN screen entirely
        # and reloads straight into the other one, for fast back-and-forth
        # testing (e.g. checking a rewards/SoR change as a normal user
        # right after setting it up as admin).
        cur_lc = (CURRENT_KID or '').strip().lower()
        if cur_lc in (ADMIN_KID, TEST_KID):
            other = TEST_KID if cur_lc == ADMIN_KID else ADMIN_KID
            tk.Button(box, text=f'🔁 Quick-switch to {other}',
                      font=("Segoe UI", 8, "bold"), bg='#21262d', fg='#58A6FF',
                      relief='flat', padx=10, pady=4, cursor='hand2',
                      command=lambda: self._dev_quick_switch(win)
                      ).pack(anchor='w', pady=(8, 0))

        def _sign_out():
            if not messagebox.askyesno(
                    "Sign Out",
                    "Sign out and return to the K-ID screen?\n\n"
                    "Unsaved chart selections will be lost.",
                    parent=win):
                return
            win.destroy()
            self.destroy()
            AppLockScreen().mainloop()

        def _change_pin():
            if not CURRENT_KID:
                messagebox.showinfo("K-ID",
                    "You're signed in as guest — create a K-ID first.", parent=win)
                return
            self._open_change_pin_dialog(parent=win)

        btn_row = tk.Frame(box, bg='#161b22')
        btn_row.pack(fill='x', pady=(10, 0))
        tk.Button(btn_row, text="🚪  Sign Out", font=("Segoe UI", 8, 'bold'),
                  bg='#21262d', fg='#58A6FF', relief='flat', padx=12, pady=4,
                  cursor='hand2', command=_sign_out).pack(side='left')
        tk.Button(btn_row, text="🔑  Change PIN", font=("Segoe UI", 8),
                  bg='#21262d', fg='#888', relief='flat', padx=12, pady=4,
                  cursor='hand2', command=_change_pin).pack(side='left', padx=(6, 0))

        # ── Cache info ────────────────────────────────────────────────────────
        cache_box = tk.Frame(win, bg='#161b22', highlightbackground='#30363D',
                             highlightthickness=1, padx=16, pady=12)
        cache_box.pack(fill='x', padx=20, pady=(10, 0))
        tk.Label(cache_box, text="💾  LOCAL CACHE  (paa_cache/ folder)",
                 font=("Segoe UI", 9, "bold"), fg='#3FB950', bg='#161b22').pack(anchor='w')
        try:
            total_sz = sum(
                os.path.getsize(os.path.join(dp, f))
                for dp, _, fs in os.walk(_CACHE_DIR) for f in fs
            )
            n_files  = sum(len(fs) for _, _, fs in os.walk(_CACHE_DIR))
            size_str = f'{total_sz/1024/1024:.1f} MB' if total_sz >= 1024*1024 else f'{total_sz/1024:.0f} KB'
            tk.Label(cache_box, text=f"{n_files} cached files · {size_str}",
                     font=("Segoe UI", 8), fg='#cdd9e5', bg='#161b22').pack(anchor='w', pady=(4, 0))
        except Exception:
            tk.Label(cache_box, text="Cache folder not found yet.",
                     font=("Segoe UI", 8), fg='#888', bg='#161b22').pack(anchor='w', pady=(4, 0))
        def _clear_cache():
            import shutil
            try:
                shutil.rmtree(_CACHE_DIR, ignore_errors=True)
                os.makedirs(_CACHE_DIR, exist_ok=True)
                messagebox.showinfo("Cache Cleared",
                    "Local cache cleared.\nAll data will be re-downloaded on next load.",
                    parent=win)
                win.destroy()
            except Exception as e:
                messagebox.showerror("Error", str(e), parent=win)
        tk.Button(cache_box, text="🗑  Clear All Cache", font=("Segoe UI", 8),
                  bg='#21262d', fg='#F85149', relief='flat', padx=10, pady=4,
                  cursor='hand2', command=_clear_cache).pack(anchor='w', pady=(6, 0))
        tk.Label(cache_box,
                 text="Prices, dividends and EPS only — your ledger and K-ID are untouched.",
                 font=("Segoe UI", 7), fg='#555', bg='#161b22',
                 wraplength=380, justify='left').pack(anchor='w', pady=(4, 0))

        tk.Button(win, text="Close", font=("Segoe UI", 10, "bold"),
                  bg='#21262d', fg='#cdd9e5', relief='flat', padx=20, pady=6,
                  cursor='hand2', command=win.destroy).pack(pady=(14, 0))

    def _open_change_pin_dialog(self, parent=None):
        """Change the signed-in K-ID's PIN."""
        win = tk.Toplevel(self)
        win.title("Change PIN")
        win.configure(bg='#0d1117')
        win.geometry("360x300")
        win.resizable(False, False)
        win.transient(parent or self)
        win.grab_set()

        tk.Label(win, text="🔑  CHANGE PIN", font=("Segoe UI", 12, "bold"),
                 fg='#58A6FF', bg='#0d1117').pack(pady=(18, 2))
        tk.Label(win, text=f"K-ID: {CURRENT_KID}", font=("Segoe UI", 8),
                 fg='#888', bg='#0d1117').pack(pady=(0, 14))

        old_var, new_var, cf_var = tk.StringVar(), tk.StringVar(), tk.StringVar()
        for lbl, var in [("Current PIN", old_var), ("New PIN (4–8 digits)", new_var),
                         ("Confirm new PIN", cf_var)]:
            tk.Label(win, text=lbl, font=("Segoe UI", 8), fg='#8b949e',
                     bg='#0d1117').pack()
            tk.Entry(win, textvariable=var, show="•", justify="center",
                     font=("Segoe UI", 13), bg='#161b22', fg='#cdd9e5',
                     insertbackground='#cdd9e5', relief="flat",
                     width=12).pack(pady=(2, 8), ipady=4)

        err_var = tk.StringVar()
        tk.Label(win, textvariable=err_var, font=("Segoe UI", 8),
                 fg='#F85149', bg='#0d1117', wraplength=300).pack()

        def _apply():
            s = load_app_settings()
            if not kid_verify(s, CURRENT_KID, old_var.get()):
                err_var.set("Current PIN is wrong."); return
            n = new_var.get()
            if not (n.isdigit() and 4 <= len(n) <= 8):
                err_var.set("New PIN must be 4–8 digits."); return
            if n != cf_var.get():
                err_var.set("New PINs don't match."); return
            acc = kid_find_account(s, CURRENT_KID)
            acc['pin_hash'] = kid_hash_pin(CURRENT_KID, n)
            save_app_settings(s)
            win.destroy()
            messagebox.showinfo("K-ID", "PIN updated.", parent=self)

        tk.Button(win, text="Update PIN", font=("Segoe UI", 10, "bold"),
                  bg='#58A6FF', fg='#0d1117', relief='flat', padx=20, pady=6,
                  cursor='hand2', command=_apply).pack(pady=(10, 0))

    def _index_description(self, label: str) -> str:
        """Live description text for the ⓘ hover on any index/fund checkbox.
        Built from the same config tuples that actually define each series,
        so the text can't drift out of sync with what the index really is."""
        # TR-Series — dividend-reinvested twin of a Core/Y-Series index.
        if label.endswith(' TR'):
            base = label[:-3]
            return (f'{label} — Total Return twin of {base}: includes dividend '
                    f'reinvestment (vs {base} itself, which is price/capital-only).')

        # Y-Series — annual IPO-cohort index.
        for ylabel, _qty, year in YSERIES_CONFIG:
            if label == ylabel:
                return f'{label} — annual cohort index of every IPO listed in {year}.'

        core_notes = {
            'MYIPO+':            'The headline composite index — every qualifying '
                                 'MYIPO+ counter across both boards, weighted by a fixed '
                                 'notional of 1,000 units × that stock\'s IPO issuing '
                                 'price (internally "Quant1" — i.e. every constituent '
                                 'enters the index at the same 1,000-unit stake size, '
                                 'not equal-dollar or float-weighted).',
            'MYIPO+ Momentum':   'A separate scoring/weighting method: instead of the '
                                 '1,000-unit stake size used by the main MYIPO+ index, '
                                 'each constituent is sized to a fixed RM1,000 notional '
                                 '— i.e. however many units RM1,000 would have bought at '
                                 'the IPO issuing price (internally "Quant2" = RM1,000 ÷ '
                                 'Issuing Price), then ranked/weighted by momentum.',
            'MYIPO+ Ace':        'The ACE Market-board subset of MYIPO+ constituents '
                                 'only (Bursa\'s growth/smaller-cap board), same '
                                 '1,000-unit stake weighting as the main index.',
            'MYIPO+ Main':       'The Main Market-board subset of MYIPO+ constituents '
                                 'only (excludes ACE-board counters), same 1,000-unit '
                                 'stake weighting as the main index.',
            'MYIPO+ Dynamic365': 'Same MYIPO+ universe and 1,000-unit stake weighting, '
                                 'but each constituent exits automatically at D+365 — '
                                 'one year after its listing.',
        }
        if label in core_notes:
            return core_notes[label]

        top_notes = {
            'MYIPO+ Top 10':  'The 10 highest-ranked MYIPO+ constituents by score/'
                              'weight, rebalanced periodically.',
            'MYIPO+ Top 20':  'The 20 highest-ranked MYIPO+ constituents by score/'
                              'weight, rebalanced periodically.',
            'MYIPO+ Top 50':  'The 50 highest-ranked MYIPO+ constituents by score/'
                              'weight, rebalanced periodically.',
            'MYIPO+ Top 100': 'The 100 highest-ranked MYIPO+ constituents by score/'
                              'weight, rebalanced periodically.',
            CHAMPIONS_LABEL:       'THEMATIC. Graduates from MYIPO+ Top 100 (rechecked '
                                   'every monthly rebalance — no carry-forward, so an '
                                   'eviction from Top 100 drops a stock here too) after a '
                                   'one-year listing/tenure gate. Ranked by a blended '
                                   'score: 30% current Top-100 rank, 40% how long it has '
                                   'been listed, 20% price performance since IPO, 10% '
                                   'dividend yield (yields above 7% are treated as a '
                                   'possible yield-trap and score slightly lower than the '
                                   '3–7% band). Top 50 by score selected, weighted by '
                                   'that same score — not equal-weight.',
            KINGS10_LABEL:         'THEMATIC. Same Top-100-graduate eligibility as '
                                   'Champions, but scored by simple points for which '
                                   'other MYIPO+ indices/boards a stock currently '
                                   'qualifies for: +2 for the flagship MYIPO+ index, +3 '
                                   'for being on the Ace or Main board, and +8 / +6 / +4 '
                                   'for reaching Top 10 / Top 20 / Top 50 respectively '
                                   '(only the single highest tier reached counts, since '
                                   'the tiers are nested). The 10 highest-scoring stocks '
                                   'are selected, weighted by that points score.',
            GEM20_LABEL:           'THEMATIC. Same skeleton as Champions, but the '
                                   'tenure weight is halved from 40% to 20%, freeing up '
                                   'a new 20% "Aristocrat" factor that rewards unbroken, '
                                   'consecutive months as a Top-100 constituent — one '
                                   'eviction resets that streak to zero. Full weighting: '
                                   '30% rank + 20% tenure + 20% Aristocrat streak + 20% '
                                   'price + 10% dividend yield. Top 20 by score selected, '
                                   'score-weighted.',
            DIVA20_LABEL:          'THEMATIC. Same one-year tenure gate as the others, '
                                   'but a deliberately simple income+momentum score with '
                                   'no tenure factor at all: 40% trailing-12-month '
                                   'dividend paid, 40% price performance since IPO, 20% '
                                   'current Top-100 rank. Top 20 by score selected, '
                                   'score-weighted.',
            BBI30_LABEL:           'THEMATIC — "Big Brand Index". Eligibility comes '
                                   'straight from a Y/N screener column in the database '
                                   'itself, not a computed factor: a stock must be '
                                   'flagged \'Y\', AND have cleared the same one-year '
                                   'tenure gate as the rest of this family (graduated / '
                                   'listed > 365 days). From that pool, the 30 stocks '
                                   'with the highest market cap AT IPO (1,000 units × '
                                   'Issuing Price — a fixed figure that doesn\'t move '
                                   'with the live price) are selected, weighted by that '
                                   'same IPO market cap.',
            ANNUAL_WINNERS_LABEL:  'The best-performing MYIPO+ constituents of the '
                                   'calendar year.',
            ANNUAL_LOSERS_LABEL:   'The worst-performing MYIPO+ constituents of the '
                                   'calendar year.',
        }
        if label in top_notes:
            return top_notes[label]

        # VFund equal-weight closed-end funds — use their own 'note' field.
        for c in VFUND_CONFIG:
            if c['label'] == label:
                ccy = c.get('ccy', '')
                return (f"{label} — {c.get('note', 'equal-weight closed-end fund')} "
                        f"(fixed basket, {ccy}, units issued once at launch).")

        # Enhanced Yield (income/covered-call) CEFs.
        for c in ENHANCED_YIELD_CONFIG:
            if c['label'] == label:
                return f"{label} — {c.get('note', 'income/covered-call fund')}."

        # Unit-trust twins ("... Fund") — tracks a Core/Y-Series index 1:1.
        if label.endswith(' Fund'):
            base = label[:-5]
            return (f'Unit trust twin of {base} — tracks its daily % change 1:1, '
                    f'with quarterly (Mar/Jun/Sep/Dec) dividend pass-through '
                    f'distribution.')

        return ''

    def _make_checkbox(self, parent, lbl):
        color = COLOR_MAP[lbl]
        row = tk.Frame(parent, bg='#161b22')
        row.pack(fill='x', padx=6, pady=1)
        tk.Label(row, text='●', bg='#161b22', fg=color,
                 font=('Segoe UI', 10)).pack(side='left')
        tk.Checkbutton(
            row, text=lbl, variable=self.check_vars[lbl],
            command=self._redraw_chart,
            bg='#161b22', fg='#cdd9e5', selectcolor='#161b22',
            activebackground='#161b22', activeforeground='#00C9FF',
            font=('Segoe UI', 8), anchor='w', relief='flat', cursor='hand2'
        ).pack(side='left', fill='x', expand=True)

        desc = self._index_description(lbl)
        if desc:
            info_lbl = tk.Label(row, text='ⓘ', bg='#161b22', fg='#555',
                                font=('Segoe UI', 8), cursor='hand2')
            info_lbl.pack(side='right', padx=(2, 4))
            guide_var = getattr(self, '_index_guide_var', None)
            if guide_var is not None:
                info_lbl.bind('<Enter>', lambda e, t=f'ⓘ {desc}': guide_var.set(t))
                info_lbl.bind('<Leave>', lambda e: guide_var.set(
                    'ⓘ Hover an index for a description.'))

    # ── Bursa Market Indices Ticker ───────────────────────────────────────────
    # KLCI + FBM EMAS + FBM70 + FBM Small Cap + FBM ACE
    # Market ticker strip config:
    # '^KLSE' fetched from Yahoo Finance (works fine)
    # Internal MYIPO+ keys read directly from self.all_frames (no yfinance needed)
    BURSA_INDICES = [
        ('^KLSE',           'KLCI',        'yahoo'),
        ('MYIPO+',          'MYIPO+',      'internal'),
        ('MYIPO+ Main',     'Main',        'internal'),
        ('MYIPO+ Ace',      'Ace',         'internal'),
        ('MYIPO+ Momentum', 'Momentum',    'internal'),
        ('MYIPO+ Top 10',   'Top 10',      'internal'),
        ('MYIPO+ Top 20',   'Top 20',      'internal'),
        ('MYIPO+ Top 50',   'Top 50',      'internal'),
        ('MYIPO+ Top 100',  'Top 100',     'internal'),
    ]

    def _build_market_ticker(self, parent):
        """Scrolling marquee ticker board — KLCI from Yahoo, MYIPO+ from all_frames.

        Rendered on a Canvas so the whole strip can slide. The item list is
        drawn twice back-to-back, so as copy A leaves the far edge copy B is
        already filling the near edge — that gives a seamless loop with no
        visible jump at the wrap point.
        """
        panel = tk.Frame(parent, bg='#0d1117',
                         highlightbackground='#21262d', highlightthickness=1)
        panel.pack(fill='x', pady=(0, 2))

        # ── Controls (right) ──────────────────────────────────────────────────
        ctl = tk.Frame(panel, bg='#0d1117')
        ctl.pack(side='right', padx=4)
        tk.Button(ctl, text='↻', font=('Segoe UI', 8), bg='#0d1117', fg='#444',
                  relief='flat', cursor='hand2', bd=0,
                  command=self._refresh_market_ticker).pack(side='right', padx=(2, 2))
        tk.Button(ctl, text='⚙', font=('Segoe UI', 8), bg='#0d1117', fg='#444',
                  relief='flat', cursor='hand2', bd=0,
                  command=self._open_marquee_settings).pack(side='right', padx=(2, 2))
        self._mkt_dir_btn = tk.Button(
            ctl, text='→', font=('Segoe UI', 8, 'bold'), bg='#0d1117', fg='#555',
            relief='flat', cursor='hand2', bd=0, width=2,
            command=self._toggle_marquee_dir)
        self._mkt_dir_btn.pack(side='right')
        self._mkt_play_btn = tk.Button(
            ctl, text='⏸', font=('Segoe UI', 8), bg='#0d1117', fg='#555',
            relief='flat', cursor='hand2', bd=0, width=2,
            command=self._toggle_marquee_run)
        self._mkt_play_btn.pack(side='right')
        self._mkt_spd_btn = tk.Button(
            ctl, text='1x', font=('Segoe UI', 7), bg='#0d1117', fg='#555',
            relief='flat', cursor='hand2', bd=0, width=3,
            command=self._cycle_marquee_speed)
        self._mkt_spd_btn.pack(side='right')
        self._mkt_time_var = tk.StringVar(value='')
        tk.Label(ctl, textvariable=self._mkt_time_var, font=('Segoe UI', 7),
                 fg='#555', bg='#0d1117').pack(side='right', padx=(0, 6))

        # ── Marquee canvas (fills the rest) ───────────────────────────────────
        self._mkt_canvas = tk.Canvas(panel, bg='#0d1117', height=22,
                                     highlightthickness=0, bd=0)
        self._mkt_canvas.pack(side='left', fill='x', expand=True)

        # Marquee state
        self._mkt_data      = {}      # sym -> (last, prev)
        self._mkt_offset    = 0.0
        self._mkt_dir       = 1       # +1 = content travels left→right, -1 = right→left
        self._mkt_running   = True
        self._mkt_speed     = 3.5     # px/frame @30fps — full loop ~30s
        self._mkt_span      = 1       # width of one full copy of the list
        self._mkt_hitboxes  = []      # (x1, x2, callback) in content coords
        self._mkt_anim_job  = None

        self._mkt_canvas.bind('<Enter>', lambda e: self._pause_marquee(True))
        self._mkt_canvas.bind('<Leave>', lambda e: self._pause_marquee(False))
        self._mkt_canvas.bind('<Button-1>', self._on_marquee_click)
        self._mkt_canvas.bind('<Motion>',   self._on_marquee_motion)
        self._mkt_canvas.bind('<Configure>', lambda e: self._draw_marquee())

        self.after(500, self._refresh_market_ticker)
        self._animate_marquee()

    # ── Marquee controls ─────────────────────────────────────────────────────
    def _toggle_marquee_dir(self):
        self._mkt_dir = -self._mkt_dir
        self._mkt_dir_btn.configure(text='→' if self._mkt_dir > 0 else '←')

    def _cycle_marquee_speed(self):
        """Cycle 1x / 2x / 0.5x — the board is long, so pace is a preference."""
        steps = [(3.5, '1x'), (7.0, '2x'), (1.75, '½x')]
        self._mkt_spd_i = (getattr(self, '_mkt_spd_i', 0) + 1) % len(steps)
        self._mkt_speed, lbl = steps[self._mkt_spd_i]
        self._mkt_spd_btn.configure(text=lbl)

    def _toggle_marquee_run(self):
        self._mkt_running = not self._mkt_running
        self._mkt_play_btn.configure(text='⏸' if self._mkt_running else '▶')

    def _pause_marquee(self, hovering: bool):
        """Hover pauses the scroll so a value can actually be read / clicked."""
        self._mkt_hover = hovering

    def _animate_marquee(self):
        try:
            if (self._mkt_running and not getattr(self, '_mkt_hover', False)
                    and self._mkt_span > 1):
                self._mkt_offset = (self._mkt_offset + self._mkt_dir * self._mkt_speed) \
                                   % self._mkt_span
                self._position_marquee()
            self._mkt_anim_job = self.after(33, self._animate_marquee)   # ~30 fps
        except tk.TclError:
            pass   # window closed

    def _position_marquee(self):
        """Slide both copies to match the current offset.
        Canvas has no absolute 'move group to x', so we track where each copy
        currently sits and apply the delta."""
        c = self._mkt_canvas
        try:
            want_a = -self._mkt_offset
            want_b = self._mkt_span - self._mkt_offset
            cur_a  = getattr(self, '_mkt_xa', 0.0)
            cur_b  = getattr(self, '_mkt_xb', float(self._mkt_span))
            c.move('grpA', want_a - cur_a, 0)
            c.move('grpB', want_b - cur_b, 0)
            self._mkt_xa, self._mkt_xb = want_a, want_b
        except tk.TclError:
            pass

    def _draw_marquee(self):
        """Render the ticker content twice, back to back, for a seamless loop."""
        c = getattr(self, '_mkt_canvas', None)
        if c is None:
            return
        c.delete('all')
        self._mkt_hitboxes = []

        F_HDR = ('Segoe UI', 6, 'bold')
        F_LBL = ('Segoe UI', 7, 'bold')
        F_VAL = ('Segoe UI', 8, 'bold')
        F_CHG = ('Segoe UI', 8)
        GAP   = 20
        y     = 11

        def _fmt(sym, last):
            """FX wants 4dp; index levels want 2dp with thousands separators.
            Low-value FX (JPY/KRW/IDR) display per-N-units, e.g. 100JPY=."""
            if sym.startswith('FX:'):
                ccy = sym.split(':', 1)[1]
                scale = self._FX_DISPLAY_SCALE.get(ccy)
                if scale:
                    return f'{last * scale:,.4f}'
                return f'{last:,.4f}'
            if sym.startswith('FXM:'):
                return f'{last:,.4f}'
            return f'{last:,.2f}'

        def _draw_copy(x0, tag):
            x = x0
            for si, (header, items) in enumerate(self._ticker_sections()):
                # Section header
                iid = c.create_text(x, y, text=header, font=F_HDR, fill='#484f58',
                                    anchor='w', tags=(tag,))
                x = c.bbox(iid)[2] + 10

                for sym, label in items:
                    last, prev = self._mkt_data.get(sym, (None, None))
                    top_n    = _TOP_LABEL_N.get(sym)      # None unless a Top-N
                    is_top   = top_n is not None
                    x_start  = x

                    iid = c.create_text(x, y, text=label, font=F_LBL,
                                        fill='#D29922' if is_top else '#888',
                                        anchor='w', tags=(tag,))
                    x = c.bbox(iid)[2] + 5

                    iid = c.create_text(x, y,
                                        text=_fmt(sym, last) if last is not None else '—',
                                        font=F_VAL, fill='#cdd9e5', anchor='w',
                                        tags=(tag,))
                    x = c.bbox(iid)[2] + 4

                    if last is not None and prev:
                        chg = last - prev
                        pct = chg / prev * 100 if prev else 0
                        sgn = '+' if chg >= 0 else ''
                        col = '#3FB950' if chg >= 0 else '#F85149'
                        arw = '▲' if chg > 0 else ('▼' if chg < 0 else '•')
                        txt = (f'{arw} {sgn}{pct:.2f}%' if sym.startswith(('FX:', 'FXM:'))
                               else f'{arw} {sgn}{chg:,.2f} ({sgn}{pct:.2f}%)')
                        iid = c.create_text(x, y, text=txt, font=F_CHG, fill=col,
                                            anchor='w', tags=(tag,))
                        x = c.bbox(iid)[2]

                    if is_top:
                        # default arg binds n now, not at click time
                        self._mkt_hitboxes.append(
                            (x_start, x, lambda n=top_n: self._open_top10_board(n)))

                    x += GAP
                    c.create_text(x - GAP / 2, y, text='·', font=F_CHG,
                                  fill='#30363d', anchor='center', tags=(tag,))

                # Divider between sections
                iid = c.create_text(x, y, text='|', font=F_LBL, fill='#21262d',
                                    anchor='w', tags=(tag,))
                x = c.bbox(iid)[2] + GAP
            return x - x0

        span = _draw_copy(0, 'grpA')
        self._mkt_span = max(span, 1)
        _draw_copy(self._mkt_span, 'grpB')
        # Copies were just drawn at their nominal spots — resync the tracker
        # before positioning, or the first move() would be off by the old delta.
        self._mkt_xa, self._mkt_xb = 0.0, float(self._mkt_span)
        self._position_marquee()

    def _marquee_content_x(self, event_x):
        """Map a click on the canvas back to a position in the content."""
        return (event_x + self._mkt_offset) % self._mkt_span

    def _on_marquee_click(self, event):
        cx = self._marquee_content_x(event.x)
        for x1, x2, cb in self._mkt_hitboxes:
            if x1 <= cx <= x2:
                cb()
                return

    def _on_marquee_motion(self, event):
        cx = self._marquee_content_x(event.x)
        over = any(x1 <= cx <= x2 for x1, x2, _ in self._mkt_hitboxes)
        self._mkt_canvas.configure(cursor='hand2' if over else '')

    def _ticker_sections(self):
        """What the marquee shows, grouped. Each section is (header, [(sym, label)]).
        BURSA_INDICES stays untouched — PTS still iterates it — so the world
        block is layered on here rather than mixed into it.
        """
        # An internal series absent from all_frames was never built — e.g.
        # Top 100 stays gated until 101 MYIPO+ IPOs exist. Showing a permanent
        # 'Top 100 —' would just be noise, so those are dropped entirely.
        frames = getattr(self, 'all_frames', {}) or {}
        my = [(s, l) for s, l, src_kind in self.BURSA_INDICES
              if src_kind != 'internal' or s in frames]
        secs = [('🇲🇾 MALAYSIA', my)]
        world = [(s, l) for s, l, _ in self.WORLD_INDICES]
        if world:
            secs.append(('🌏 WORLD', world))
        # Derive FX from the currencies actually in use — add an index and
        # its FX leg follows automatically. Low-value currencies (JPY, KRW,
        # IDR) get a scaled label ("100JPY=") instead of the raw per-1 rate.
        ccys = self._fx_ccys()
        secs.append(('💱 FX', [(f'FX:{c}', self._fx_display_label(c)) for c in ccys]))
        # Major FX crosses — marquee-only, not tied to any index/holding.
        secs.append(('💵 MAJOR FX', [(sym, label) for sym, label, _ in self.MAJOR_FX_PAIRS]))

        hidden = set(self._marquee_hidden_syms())
        if hidden:
            secs = [(hdr, [(s, l) for s, l in items if s not in hidden])
                    for hdr, items in secs]
            secs = [(hdr, items) for hdr, items in secs if items]
        return secs

    def _marquee_hidden_syms(self) -> set:
        """Symbols the user has chosen to hide from the marquee — persisted
        in app_settings so the choice survives restarts."""
        if not hasattr(self, '_marquee_hidden_cache'):
            settings = load_app_settings()
            self._marquee_hidden_cache = set(settings.get('marquee_hidden', []) or [])
        return self._marquee_hidden_cache

    def _marquee_all_items(self):
        """Every (section header, sym, label) the marquee could show, for
        the ⚙ selection dialog — unfiltered by current hide-prefs."""
        frames = getattr(self, 'all_frames', {}) or {}
        my = [(s, l) for s, l, src_kind in self.BURSA_INDICES
              if src_kind != 'internal' or s in frames]
        out = [('🇲🇾 MALAYSIA', s, l) for s, l in my]
        out += [('🌏 WORLD', s, l) for s, l, _ in self.WORLD_INDICES]
        ccys = self._fx_ccys()
        out += [('💱 FX', f'FX:{c}', self._fx_display_label(c)) for c in ccys]
        out += [('💵 MAJOR FX', sym, label) for sym, label, _ in self.MAJOR_FX_PAIRS]
        return out

    # Plain-English guide for each MYIPO+ series — shown as a hover
    # description in the ⚙ marquee picker so a user can tell what a name
    # like "Momentum" or "Top 50" actually means before deciding to show it.
    _MYIPO_INDEX_GUIDE = {
        'KLCI':      'FBM KLCI — Bursa Malaysia\'s official benchmark index '
                     '(the 30 largest Main Market companies), fetched live from Yahoo.',
        'MYIPO+':    'MYIPO+ — the headline composite index tracking every '
                     'qualifying MYIPO+ counter across both boards.',
        'Main':      'MYIPO+ Main — the Main Market-board subset of MYIPO+ '
                     'constituents only (excludes ACE-board counters).',
        'Ace':       'MYIPO+ Ace — the ACE Market-board subset of MYIPO+ '
                     'constituents only (Bursa\'s growth/smaller-cap board).',
        'Momentum':  'MYIPO+ Momentum — instead of the standard 1,000-unit stake '
                     'size, each constituent is sized to a fixed RM1,000 notional '
                     '(however many units RM1,000 buys at the IPO issuing price), '
                     'then ranked/weighted by momentum.',
        'Top 10':    'MYIPO+ Top 10 — the 10 highest-ranked MYIPO+ '
                     'constituents by score/weight, rebalanced periodically.',
        'Top 20':    'MYIPO+ Top 20 — the 20 highest-ranked MYIPO+ '
                     'constituents by score/weight, rebalanced periodically.',
        'Top 50':    'MYIPO+ Top 50 — the 50 highest-ranked MYIPO+ '
                     'constituents by score/weight, rebalanced periodically.',
        'Top 100':   'MYIPO+ Top 100 — the 100 highest-ranked MYIPO+ '
                     'constituents by score/weight, rebalanced periodically.',
    }

    def _open_marquee_settings(self):
        """⚙ — let the user pick exactly which marquee items show. Grouped
        by section, remembers the choice via app_settings. MYIPO+ series
        entries get a hover guide (bottom description panel) since names
        like "Momentum" or "Top 50" aren't self-explanatory on their own."""
        win = tk.Toplevel(self)
        win.title('Marquee — Choose what to show')
        win.configure(bg='#0d1117')
        win.geometry('380x520')
        win.transient(self)

        tk.Label(win, text='⚙  MARQUEE — VISIBLE ITEMS', font=('Segoe UI', 11, 'bold'),
                 fg='#cdd9e5', bg='#0d1117').pack(pady=(12, 2))
        tk.Label(win, text='Unchecked items are hidden from the scrolling ticker. '
                            'Hover a ⓘ MYIPO+ item for what it means.',
                 font=('Segoe UI', 8), fg='#888', bg='#0d1117',
                 wraplength=350, justify='left').pack(pady=(0, 8), padx=12)

        # ── Guide/description panel — updates on hover, sits above the list
        # so it doesn't shift the checklist layout as the user moves around.
        guide_var = tk.StringVar(value='')
        guide_lbl = tk.Label(win, textvariable=guide_var, font=('Segoe UI', 8),
                             fg='#00C9FF', bg='#0d1117', wraplength=350,
                             justify='left', anchor='w', height=3)
        guide_lbl.pack(fill='x', padx=12, pady=(0, 4))

        canvas = tk.Canvas(win, bg='#0d1117', highlightthickness=0)
        vbar = ttk.Scrollbar(win, orient='vertical', command=canvas.yview)
        canvas.configure(yscrollcommand=vbar.set)
        vbar.pack(side='right', fill='y')
        canvas.pack(side='left', fill='both', expand=True, padx=(12, 0))
        body = tk.Frame(canvas, bg='#0d1117')
        canvas.create_window((0, 0), window=body, anchor='nw')
        body.bind('<Configure>', lambda e: canvas.configure(scrollregion=canvas.bbox('all')))

        def _show_guide(text):
            guide_var.set(text)
        def _clear_guide():
            guide_var.set('')

        hidden = self._marquee_hidden_syms()
        vars_by_sym = {}
        last_hdr = None
        for hdr, sym, label in self._marquee_all_items():
            if hdr != last_hdr:
                tk.Label(body, text=hdr, font=('Segoe UI', 8, 'bold'),
                         fg='#00C9FF', bg='#0d1117').pack(anchor='w', pady=(8, 2))
                last_hdr = hdr
            var = tk.BooleanVar(value=sym not in hidden)
            guide_text = self._MYIPO_INDEX_GUIDE.get(label)
            row_text = f'ⓘ {label}' if guide_text else label
            cb = tk.Checkbutton(body, text=row_text, variable=var, font=('Segoe UI', 9),
                                fg='#cdd9e5', bg='#0d1117', selectcolor='#161b22',
                                activebackground='#0d1117', activeforeground='#cdd9e5',
                                anchor='w')
            cb.pack(fill='x', anchor='w')
            if guide_text:
                cb.bind('<Enter>', lambda e, t=guide_text: _show_guide(t))
                cb.bind('<Leave>', lambda e: _clear_guide())
            vars_by_sym[sym] = var

        def _save():
            newly_hidden = {sym for sym, var in vars_by_sym.items() if not var.get()}
            self._marquee_hidden_cache = newly_hidden
            settings = load_app_settings()
            settings['marquee_hidden'] = sorted(newly_hidden)
            save_app_settings(settings)
            self._draw_marquee()
            win.destroy()

        btn_row = tk.Frame(win, bg='#0d1117')
        btn_row.pack(fill='x', padx=12, pady=10)
        tk.Button(btn_row, text='💾 Save', command=_save, bg='#3FB950', fg='#0d1117',
                  relief='flat', padx=12, pady=4, cursor='hand2',
                  font=('Segoe UI', 9, 'bold')).pack(side='left')
        tk.Button(btn_row, text='Cancel', command=win.destroy, bg='#21262d', fg='#cdd9e5',
                  relief='flat', padx=12, pady=4, cursor='hand2',
                  font=('Segoe UI', 9)).pack(side='left', padx=(8, 0))

    def _refresh_market_ticker(self):
        """Refresh the marquee — internal MYIPO+ series are free, KLCI /
        world indices / FX are fetched in parallel with a 5-min disk cache."""
        import threading as _th

        def _worker():
            import yfinance as _yf
            from concurrent.futures import ThreadPoolExecutor, as_completed
            results = {}

            # ── Internal MYIPO+ series — instant, no network needed ───────────
            for sym, label, source in self.BURSA_INDICES:
                if source != 'internal':
                    continue
                try:
                    df = self.all_frames.get(sym)
                    if df is None or df.empty:
                        continue
                    if sym in df.columns:
                        s = df[sym].dropna()
                    else:
                        num_cols = df.select_dtypes('number').columns
                        if len(num_cols) == 0:
                            continue
                        s = df[num_cols[0]].dropna()
                    if len(s) < 1:
                        continue
                    last = float(s.iloc[-1])
                    prev = float(s.iloc[-2]) if len(s) >= 2 else last
                    results[sym] = (last, prev)
                except Exception:
                    pass

            # ── Yahoo symbols: KLCI + every world index, fetched together ─────
            def _alt_prefix_sym(sym):
                """Sector Select indices show up under either ^IXxx or
                ^SIXxx on Yahoo depending on the sector — try whichever
                prefix the caller didn't already use."""
                if sym.startswith('^SIX'):
                    return '^IX' + sym[4:]
                if sym.startswith('^IX'):
                    return '^SIX' + sym[3:]
                return None

            def _fetch(sym):
                key = f'tick_{sym.replace("^", "")}'
                cached = cache_get_live_dict(key, _TTL_LIVE)
                if cached:
                    return sym, cached.get('last'), cached.get('prev')
                candidates = [sym]
                alt = _alt_prefix_sym(sym)
                if alt:
                    candidates.append(alt)
                for try_sym in candidates:
                    try:
                        t    = _yf.Ticker(try_sym)
                        fi   = t.fast_info
                        last = getattr(fi, 'last_price', None) or getattr(fi, 'lastPrice', None)
                        prev = getattr(fi, 'previous_close', None) or getattr(fi, 'previousClose', None)
                        if last is None or prev is None:
                            h = t.history(period='2d')
                            if not h.empty:
                                last = float(h['Close'].iloc[-1])
                                prev = float(h['Close'].iloc[-2]) if len(h) > 1 else last
                        if last:
                            last = float(last)
                            prev = float(prev) if prev else last
                            cache_set_live_dict(key, {'last': last, 'prev': prev})
                            return sym, last, prev
                    except Exception:
                        continue
                return sym, None, None

            yahoo_syms = ['^KLSE'] + [s for s, _, _ in self.WORLD_INDICES]
            try:
                with ThreadPoolExecutor(max_workers=min(8, len(yahoo_syms))) as ex:
                    for fut in as_completed([ex.submit(_fetch, s) for s in yahoo_syms]):
                        sym, last, prev = fut.result()
                        if last is not None:
                            results[sym] = (last, prev)
            except Exception:
                pass
            # Keep the KLCI cache key the ZDWS level lookup also reads
            if '^KLSE' in results:
                l, p = results['^KLSE']
                cache_set_live_dict('market_indices_klci',
                                    {'^KLSE': {'last': l, 'prev': p}})

            # ── FX pairs — one per currency in WORLD_INDICES ──────────────────
            # TWD has no direct TWDMYR=X pair on Yahoo, only USDTWD=X, so it's
            # derived through the USD leg instead of the generic direct fetch.
            for ccy in self._fx_ccys():
                if ccy == 'TWD':
                    twd_rate = self._zdws_twd_to_myr()
                    if twd_rate is not None:
                        results['FX:TWD'] = (twd_rate, twd_rate)
                    continue
                sym, last, prev = _fetch(f'{ccy}MYR=X')
                if last is not None:
                    results[f'FX:{ccy}'] = (last, prev)

            # ── Major FX crosses (marquee-only, no MYR leg) ────────────────────
            for mkey, _label, ysym in self.MAJOR_FX_PAIRS:
                sym, last, prev = _fetch(ysym)
                if last is not None:
                    results[mkey] = (last, prev)

            self.after(0, lambda: self._apply_market_data(results))

        _th.Thread(target=_worker, daemon=True).start()

    def _apply_market_data(self, results):
        """Store fresh values and redraw the marquee content."""
        from datetime import datetime as _DT
        self._mkt_data = dict(results or {})
        self._draw_marquee()
        self._mkt_time_var.set(_DT.now().strftime('%H:%M'))

