        # ── Scrollable body ──
        wrap = tk.Frame(win, bg='#0d1117')
        wrap.pack(fill='both', expand=True)
        canvas = tk.Canvas(wrap, bg='#0d1117', highlightthickness=0)
        vsb    = ttk.Scrollbar(wrap, orient='vertical', command=canvas.yview)
