    def _open_suggestion_chat(self, parent=None):
        """💬 Suggestion / feedback box — available to users on ALL tiers
        (Free, Kopitiam Kopi, ZusCoffer, StarBockers, Beta Supporter).
        Messages are stored locally in paa_settings.json under
        'suggestions' so an admin can review them later; there is no
        live network chat involved."""
        pts = self._pts_load() if hasattr(self, '_pts_load') else {}
        cur_tier = pts.get('tier', 'Free') if isinstance(pts, dict) else 'Free'
        kid = (CURRENT_KID or 'guest').strip().lower() if 'CURRENT_KID' in globals() else 'guest'

        if cur_tier == 'Free':
            messagebox.showinfo(
                'Supporter Perk',
                '💬 Chat & Suggestions is a supporter perk.\n\n'
                'Upgrade to Kopitiam Kopi, ZusCoffer, StarBockers or the '
                'Beta Supporter tier to chat with us and suggest features.',
                parent=parent or self)
            return

        box = tk.Toplevel(parent or self)
        box.title('💬 Suggestions & Chat')
        box.configure(bg='#0d1117')
        box.geometry('420x420')
        box.transient(parent or self)

        tk.Label(box, text='💬  SUGGESTIONS & CHAT', font=('Segoe UI', 12, 'bold'),
                 fg='#FFD700', bg='#0d1117').pack(pady=(12, 2))
        tk.Label(box, text=f'Signed in as {kid}  •  Tier: {cur_tier}',
                 font=('Segoe UI', 8), fg='#8b949e', bg='#0d1117').pack()
        tk.Label(box, text='Open to all 4 supporter tiers — tell us what '
                           "you'd like to see next (e.g. HK/SG markets, "
                           'new reward types, UI ideas).',
                 font=('Segoe UI', 8), fg='#cdd9e5', bg='#0d1117',
                 wraplength=380, justify='left').pack(padx=14, pady=(4, 8))

        txt = tk.Text(box, height=8, width=44, bg='#161b22', fg='#cdd9e5',
                      insertbackground='#cdd9e5', wrap='word', relief='flat')
        txt.pack(padx=14, pady=(0, 8), fill='both', expand=True)

        status_lbl = tk.Label(box, text='', font=('Segoe UI', 8),
                              fg='#3FB950', bg='#0d1117')
        status_lbl.pack()

        def send_suggestion():
            msg = txt.get('1.0', 'end').strip()
            if not msg:
                status_lbl.config(text='Type a message first.', fg='#F85149')
                return
            import datetime as _dt
            settings = load_app_settings()
            entry = {
                'kid': kid, 'tier': cur_tier, 'message': msg,
                'sent': _dt.datetime.now().strftime('%Y-%m-%d %H:%M'),
            }
            settings.setdefault('suggestions', []).append(entry)
            save_app_settings(settings)
            txt.delete('1.0', 'end')
            status_lbl.config(text='✓ Sent — thanks for the suggestion!', fg='#3FB950')

        tk.Button(box, text='Send Suggestion', command=send_suggestion,
                 bg='#238636', fg='white', activebackground='#2ea043',
                 activeforeground='white', relief='flat', cursor='hand2',
                 font=('Segoe UI', 9, 'bold')).pack(pady=(0, 12), padx=14, fill='x')

    def _open_admin_credit_universe(self):
        """🧾 Credit Universe — every credit event, for every K-ID, in one
        merged/sorted ledger. Admin-only audit trail across the whole
        user base (the "universe" of credit issuance)."""
        if (CURRENT_KID or '').strip().lower() != ADMIN_KID:
            messagebox.showwarning('Admin', 'Admin access only.', parent=self)
            return
        s       = load_app_settings()
        wallets = s.get('pts_by_user', {})

        win = tk.Toplevel(self)
        win.title('🧾 Credit Universe — All K-IDs')
        win.configure(bg='#0d1117')
        win.geometry('820x520')

        hdr = tk.Frame(win, bg='#0d1117'); hdr.pack(fill='x', padx=12, pady=(10, 4))
        tk.Label(hdr, text='🧾  CREDIT UNIVERSE  ·  ALL K-IDS',
                 font=('Segoe UI', 12, 'bold'), fg='#FFD700', bg='#0d1117').pack(side='left')

        rows = []
        total_issued = 0.0
        for kid, w in wallets.items():
            for entry in w.get('credit_log', []):
                delta = entry.get('delta', 0)
                total_issued += delta
                rows.append((entry.get('ts', ''), kid or '(guest)', delta,
                             entry.get('balance', 0), entry.get('reason', '')))
        rows.sort(key=lambda r: r[0], reverse=True)   # newest first

        tk.Label(hdr, text=f'{len(rows):,} event(s)  ·  net {total_issued:+,.0f} Cr across '
                           f'{len(wallets)} account(s)',
                 font=('Segoe UI', 8), fg='#8b949e', bg='#0d1117').pack(side='right')

        cols = ('Date/Time', 'K-ID', 'Change', 'Balance After', 'Reason')
        tree = ttk.Treeview(win, columns=cols, show='headings', height=20)
        for c, wd, anch in zip(cols, (140, 100, 90, 110, 320), ('center', 'center', 'e', 'e', 'w')):
            tree.heading(c, text=c)
            tree.column(c, width=wd, anchor=anch)
        vsb = ttk.Scrollbar(win, orient='vertical', command=tree.yview)
        tree.configure(yscrollcommand=vsb.set)
        tree.pack(side='left', fill='both', expand=True, padx=(12, 0), pady=(0, 12))
        vsb.pack(side='left', fill='y', pady=(0, 12), padx=(0, 12))
        tree.tag_configure('pos', foreground='#3FB950')
        tree.tag_configure('neg', foreground='#F85149')

        for ts, kid, delta, bal, reason in rows:
            tree.insert('', 'end', tags=('pos' if delta >= 0 else 'neg',),
                        values=(ts, kid, f'{delta:+,.0f}', f'{bal:,.0f}', reason))
        if not rows:
            tk.Label(win, text='No credit activity recorded yet across any K-ID.',
                     font=('Segoe UI', 9), fg='#8b949e', bg='#0d1117').pack(pady=20)

    def _tier_days_active(self, w: dict) -> int:
        """Days the wallet's current tier has been active (0 for Free/unset)."""
        import datetime as _dt
        try:
            start = _dt.date.fromisoformat(w.get('tier_started', ''))
            return (_dt.date.today() - start).days
        except Exception:
            return 0

    def _rewards_open_subscribe(self, tier_name: str):
        """Open the tier's Stripe-HOSTED Payment Link in the browser, tagged
        with ?client_reference_id=<K-ID>. The entire payment flow (card entry,
        3DS, renewal) runs on Stripe's hosted page — nothing local handles
        card data and no backend exists on our side. Activation happens when
        the admin's Sync pulls the resulting subscription and matches the
        reference back to this K-ID."""
        import urllib.parse
        kid = (CURRENT_KID or '').strip().lower()
        if not kid:
            messagebox.showwarning('Subscribe',
                'Sign in with a K-ID first — the payment needs to be tagged '
                'to your account.', parent=self)
            return
        link = self._stripe_paylink(tier_name)
        if not link:
            messagebox.showinfo('Subscribe',
                f'No Payment Link configured for {tier_name} yet.\n'
                f'(Admin: create the weekly Payment Link in the Stripe '
                f'Dashboard and paste it in the Admin Dashboard.)', parent=self)
            return
        proceed = messagebox.askokcancel('Before you pay',
            '⚠️  Please note:\n\n'
            'This is a personal, independently-run project — not a registered '
            'company. Your payment is processed by Stripe to the developer\'s '
            'own personal Stripe account, under their own name, not a business '
            'name.\n\n'
            'Click OK to continue to Stripe\'s hosted checkout.', parent=self)
        if not proceed:
            return
        sep = '&' if '?' in link else '?'
        _webbrowser.open(f'{link}{sep}client_reference_id={urllib.parse.quote(kid)}')
        messagebox.showinfo('Subscribe',
            f'💳 Stripe checkout opened in your browser for {tier_name}.\n\n'
            f'Once payment completes, this app will auto-verify and '
            f'activate your tier — no need to do anything else.', parent=self)
        # Poll every 10s for up to 90s so activation happens while the app
        # stays open in the background, not just on next launch.
        for delay in range(10_000, 91_000, 10_000):
            self.after(delay, lambda: self._stripe_autoverify_current_user(silent=False))

    def _admin_emergency_lock(self, parent):
        """🚨 Compromised-secret response: lock admin1 out of the normal
        PIN+R-Code path entirely and mint a single-use recovery code —
        16 hex chars (0-f), cryptographically random via secrets. Only the
        code's SHA-256 is stored; the plaintext is shown exactly once here,
        so copy it somewhere safe — recovering without it means editing
        paa_settings.json by hand."""
        import secrets as _sec, hashlib as _hl
        if not messagebox.askyesno('Emergency Lock',
                'Activate the emergency lock?\n\n'
                '• admin1 login via PIN + R-Code will be DISABLED\n'
                '• A one-time 16-hex recovery code will be generated\n'
                '• Recovery requires that code and sets a NEW R-Code',
                parent=parent):
            return
        code = _sec.token_hex(8)   # 16 hex characters, 0-f
        st = load_app_settings()
        st['admin_emergency_lock']   = True
        st['admin_recovery_sha256']  = _hl.sha256(code.encode()).hexdigest()
        save_app_settings(st)
        dlg = tk.Toplevel(parent)
        dlg.title('🚨 Recovery Code')
        dlg.configure(bg='#0d1117')
        dlg.geometry('380x180')
        dlg.transient(parent); dlg.grab_set()
        tk.Label(dlg, text='🚨  EMERGENCY LOCK ACTIVE', font=('Segoe UI', 11, 'bold'),
                 fg='#F85149', bg='#0d1117').pack(pady=(14, 4))
        tk.Label(dlg, text='Your ONE-TIME recovery code — shown only once, copy it now:',
                 font=('Segoe UI', 8), fg='#cdd9e5', bg='#0d1117').pack()
        ce = tk.Entry(dlg, font=('Consolas', 14, 'bold'), justify='center',
                      bg='#161b22', fg='#FFD700', relief='flat',
                      highlightbackground='#F85149', highlightthickness=1)
        ce.insert(0, code)
        ce.config(state='readonly', readonlybackground='#161b22')
        ce.pack(pady=8, padx=30, fill='x')
        tk.Label(dlg, text='Next admin1 login will demand this code and force a new R-Code.',
                 font=('Segoe UI', 7), fg='#8b949e', bg='#0d1117').pack()
        tk.Button(dlg, text='I saved it', font=('Segoe UI', 9, 'bold'),
                  bg='#21262d', fg='#cdd9e5', relief='flat', padx=14, pady=4,
                  cursor='hand2', command=dlg.destroy).pack(pady=(6, 10))

    def _open_admin_dashboard(self):
        """🛡 Admin-only overview: every K-ID's wallet at a glance (tier,
        credits, streak, last login) with live online status from the
        presence heartbeat, plus the raffle control panel. Gated hard on the
        reserved admin account — the button never renders for anyone else,
        and this method double-checks anyway."""
        if (CURRENT_KID or '').strip().lower() != ADMIN_KID:
            messagebox.showwarning('Admin', 'Admin access only.', parent=self)
            return
        import datetime as _dt

        win = tk.Toplevel(self)
        win.title('🛡 PAA Admin Dashboard')
        win.configure(bg='#0d1117')
        win.geometry('960x680')

        hdr = tk.Frame(win, bg='#0d1117'); hdr.pack(fill='x', padx=12, pady=(10, 4))
        tk.Label(hdr, text='🛡  ADMIN DASHBOARD', font=('Segoe UI', 13, 'bold'),
                 fg='#F85149', bg='#0d1117').pack(side='left')
        tk.Button(hdr, text='↻ Refresh', font=('Segoe UI', 8, 'bold'),
                  bg='#21262d', fg='#cdd9e5', relief='flat', padx=10, pady=3,
                  cursor='hand2',
                  command=lambda: (win.destroy(), self._open_admin_dashboard())
                  ).pack(side='right')
        tk.Button(hdr, text='🚨 Emergency Lock', font=('Segoe UI', 8, 'bold'),
                  bg='#2a0a0a', fg='#F85149', relief='flat', padx=10, pady=3,
                  cursor='hand2',
                  command=lambda: self._admin_emergency_lock(win)
                  ).pack(side='right', padx=(0, 6))
        tk.Button(hdr, text='🧾 Credit Universe', font=('Segoe UI', 8, 'bold'),
                  bg='#21262d', fg='#FFD700', relief='flat', padx=10, pady=3,
                  cursor='hand2',
                  command=self._open_admin_credit_universe
                  ).pack(side='right', padx=(0, 6))

        s        = load_app_settings()
        wallets  = s.get('pts_by_user', {})
        presence = s.get('presence', {})
        now      = _dt.datetime.now()

        def _status(kid):
            rec = presence.get(kid, {})
            seen_s = rec.get('last_seen', '')
            try:
                seen = _dt.datetime.strptime(seen_s, '%Y-%m-%d %H:%M:%S')
                if (now - seen).total_seconds() <= PRESENCE_ONLINE_SECS:
                    return '🟢 Online', seen_s
                return '⚪ Offline', seen_s
            except Exception:
                return '⚪ Offline', '—'

        n_online = sum(1 for k in wallets
                       if _status(k)[0].startswith('🟢'))
        tk.Label(win, text=f'{len(wallets)} account(s)  ·  {n_online} online now  '
                           f'(online = heartbeat within {PRESENCE_ONLINE_SECS // 60} min)',
                 font=('Segoe UI', 8), fg='#8b949e', bg='#0d1117',
                 anchor='w', padx=12).pack(fill='x')

        # ── Users table ───────────────────────────────────────────────────────
        stripe_subs = s.get('stripe_subs', {})
        uf = tk.Frame(win, bg='#0d1117'); uf.pack(fill='both', expand=True, padx=12, pady=(4, 6))
        cols = ('K-ID', 'Status', 'Tier', 'Sub Days', 'Sub Status', 'Credits',
                'Streak', 'Last Login', 'Last Seen')
        utree = ttk.Treeview(uf, columns=cols, show='headings', height=10)
        for c, wd in zip(cols, (100, 75, 105, 65, 105, 85, 55, 130, 130)):
            utree.heading(c, text=c)
            utree.column(c, width=wd, anchor='center')
        vsb = ttk.Scrollbar(uf, orient='vertical', command=utree.yview)
        utree.configure(yscrollcommand=vsb.set)
        utree.grid(row=0, column=0, sticky='nsew'); vsb.grid(row=0, column=1, sticky='ns')
        uf.rowconfigure(0, weight=1); uf.columnconfigure(0, weight=1)
        utree.tag_configure('on',  foreground='#3FB950')
        utree.tag_configure('off', foreground='#8b949e')
        for kid, w in sorted(wallets.items()):
            st, seen_s = _status(kid)
            rec = presence.get(kid, {})
            w_tier = w.get('tier', 'Free')
            days   = self._tier_days_active(w) if w_tier != 'Free' else 0
            ssub   = stripe_subs.get(kid)
            sub_st = (f"{ssub['status']} → {ssub['period_end']}" if ssub
                      else ('manual' if w_tier != 'Free' else '—'))
            utree.insert('', 'end', tags=('on' if st.startswith('🟢') else 'off',),
                         values=(kid or '(guest)', st, w_tier,
                                 days if w_tier != 'Free' else '—', sub_st,
                                 f"{w.get('credits', 0):,.0f}",
                                 w.get('login_streak_len', 0),
                                 rec.get('last_login', '—'), seen_s))

        tk.Label(win, text='Double-click a row to view that K-ID\'s credit history.',
                 font=('Segoe UI', 8), fg='#8b949e', bg='#0d1117',
                 anchor='w', padx=12).pack(fill='x')

        def _on_row_dclick(event):
            sel = utree.selection()
            if not sel:
                return
            kid = utree.item(sel[0], 'values')[0]
            key = '' if kid == '(guest)' else kid
            w = wallets.get(key)
            if w is not None:
                self._open_credit_history_popup(w, title_kid=kid)
        utree.bind('<Double-1>', _on_row_dclick)

        # ── Raffle control panel ──────────────────────────────────────────────
        rf = tk.Frame(win, bg='#161b22', highlightbackground='#30363d',
                      highlightthickness=1)
        rf.pack(fill='x', padx=12, pady=(0, 10))
        tk.Label(rf, text='🎟️  RAFFLE CONTROL', font=('Segoe UI', 10, 'bold'),
                 fg='#FFD700', bg='#161b22').pack(anchor='w', padx=8, pady=(6, 2))
        for tname, cfg in self.RAFFLES.items():
            row = tk.Frame(rf, bg='#161b22'); row.pack(fill='x', padx=8, pady=2)
            entrants = self._raffle_entrants(tname)
            last = next((h for h in reversed(s.get('raffle_history', []))
                         if h['tier'] == tname), None)
            last_txt = (f"last: {last['date']} → {last['winner']}" if last
                        else 'no draw yet')
            tk.Label(row, text=f'{tname}  ·  {cfg["prize"]}  ·  '
                               f'{len(entrants)} eligible '
                               f'({", ".join(entrants) if entrants else "none"})  ·  {last_txt}',
                     font=('Segoe UI', 8), fg='#cdd9e5', bg='#161b22',
                     wraplength=650, justify='left').pack(side='left')
            tk.Button(row, text='🎲 Draw', font=('Segoe UI', 8, 'bold'),
                      bg='#21262d', fg='#FFD700', relief='flat', padx=10, pady=3,
                      cursor='hand2',
                      command=lambda t=tname: self._raffle_run_draw(t)
                      ).pack(side='right')
        hist = s.get('raffle_history', [])
        if hist:
            tk.Label(rf, text='History: ' + '  |  '.join(
                         f"{h['date']} {h['tier']}: {h['winner']}" for h in hist[-5:][::-1]),
                     font=('Segoe UI', 7), fg='#8b949e', bg='#161b22',
                     wraplength=800, justify='left').pack(anchor='w', padx=8, pady=(2, 6))

        # ── Stripe panel ──────────────────────────────────────────────────────
        sf = tk.Frame(win, bg='#161b22', highlightbackground='#635BFF',
                      highlightthickness=1)
        sf.pack(fill='x', padx=12, pady=(0, 10))
        tk.Label(sf, text='💳  STRIPE SUBSCRIPTIONS', font=('Segoe UI', 10, 'bold'),
                 fg='#635BFF', bg='#161b22').pack(anchor='w', padx=8, pady=(6, 2))
        key_row = tk.Frame(sf, bg='#161b22'); key_row.pack(fill='x', padx=8, pady=2)
        tk.Label(key_row, text='Secret key (sk_test_… in sandbox):',
                 font=('Segoe UI', 8), fg='#cdd9e5', bg='#161b22').pack(side='left')
        key_var = tk.StringVar(value=s.get('stripe_api_key', ''))
        tk.Entry(key_row, textvariable=key_var, show='•', width=34,
                 font=('Segoe UI', 8), bg='#0d1117', fg='#cdd9e5',
                 insertbackground='#635BFF', relief='flat',
                 highlightbackground='#30363d', highlightthickness=1
                 ).pack(side='left', padx=6)
        def _save_key():
            st2 = load_app_settings()
            st2['stripe_api_key'] = key_var.get().strip()
            save_app_settings(st2)
            messagebox.showinfo('Stripe', 'API key saved (this machine only).', parent=win)
        tk.Button(key_row, text='Save key', font=('Segoe UI', 7, 'bold'),
                  bg='#21262d', fg='#cdd9e5', relief='flat', padx=8, pady=2,
                  cursor='hand2', command=_save_key).pack(side='left')

        sync_var = tk.StringVar(value=f"Last sync: {s.get('stripe_last_sync', 'never')}")
        tk.Label(sf, textvariable=sync_var, font=('Segoe UI', 7), fg='#8b949e',
                 bg='#161b22').pack(anchor='w', padx=8)

        # Restricted key — shipped inside the app so EVERY user's copy can
        # self-verify their own purchase automatically. Create TWO of these
        # in Stripe Dashboard → Developers → API keys → "Create restricted
        # key": one while in Test mode (rk_test_…), one in Live mode
        # (rk_live_…). Each needs ONLY "Checkout Sessions: Read" +
        # "Subscriptions: Read" — leave everything else "None". Never put
        # a secret key (sk_…) here. Flip the switch below once you're done
        # testing with sk_test-era flows and ready to take real payments.
        mode_row = tk.Frame(sf, bg='#161b22'); mode_row.pack(fill='x', padx=8, pady=(6, 2))
        tk.Label(mode_row, text='Mode:', font=('Segoe UI', 8, 'bold'),
                 fg='#cdd9e5', bg='#161b22').pack(side='left')
        mode_var = tk.StringVar(value=s.get('stripe_mode', 'test'))
        def _save_mode(*_a):
            st2 = load_app_settings()
            st2['stripe_mode'] = mode_var.get()
            save_app_settings(st2)
        for val, lbl, col in (('test', '🧪 Test (sandbox)', '#D29922'),
                               ('live', '🔴 Live (real payments)', '#F85149')):
            tk.Radiobutton(mode_row, text=lbl, variable=mode_var, value=val,
                           font=('Segoe UI', 8), fg=col, bg='#161b22',
                           selectcolor='#0d1117', activebackground='#161b22',
                           activeforeground=col, command=_save_mode
                           ).pack(side='left', padx=6)

        rkeys = (('stripe_restricted_key_test', 'Test restricted key (rk_test_…):'),
                 ('stripe_restricted_key_live', 'Live restricted key (rk_live_…):'))
        rkey_vars = {}
        for setting_key, label in rkeys:
            rkey_row = tk.Frame(sf, bg='#161b22'); rkey_row.pack(fill='x', padx=8, pady=2)
            tk.Label(rkey_row, text=label, font=('Segoe UI', 8), fg='#cdd9e5',
                     bg='#161b22', width=28, anchor='w').pack(side='left')
            v = tk.StringVar(value=s.get(setting_key, ''))
            rkey_vars[setting_key] = v
            tk.Entry(rkey_row, textvariable=v, show='•', width=26,
                     font=('Segoe UI', 8), bg='#0d1117', fg='#cdd9e5',
                     insertbackground='#635BFF', relief='flat',
                     highlightbackground='#30363d', highlightthickness=1
                     ).pack(side='left', padx=6)
        def _save_rkeys():
            st2 = load_app_settings()
            for setting_key, v in rkey_vars.items():
                st2[setting_key] = v.get().strip()
            save_app_settings(st2)
            messagebox.showinfo('Stripe',
                'Restricted keys saved. Auto-verify uses whichever mode is '
                'selected above — switch to Live once you\'re ready to ship.',
                parent=win)
        tk.Button(sf, text='Save keys', font=('Segoe UI', 7, 'bold'),
                  bg='#21262d', fg='#cdd9e5', relief='flat', padx=8, pady=2,
                  cursor='hand2', command=_save_rkeys).pack(anchor='w', padx=8, pady=(2, 2))
        tk.Label(sf, text='⚠️  Grant ONLY "Checkout Sessions: Read" + "Subscriptions: Read" '
                          'on each key (both read-only) — nothing else. They ship inside the '
                          'app, so they must never be able to write, charge, or refund.',
                 font=('Segoe UI', 7), fg='#D29922', bg='#161b22',
                 wraplength=560, justify='left').pack(anchor='w', padx=8, pady=(0, 4))

        # Hosted Payment Links — one per paid tier, created in the Stripe
        # Dashboard (Products → Payment Links, weekly recurring price).
        # Users pay on Stripe's hosted page; the app only opens the URL.
        pl = s.get('stripe_paylinks', {})
        pl_vars = {}
        for tname, t in self.PAA_TIERS.items():
            if tname == 'Free':
                continue
            prow = tk.Frame(sf, bg='#161b22'); prow.pack(fill='x', padx=8, pady=1)
            tk.Label(prow, text=f'{t["badge"]} {tname} link (RM{t["price_wk"]:.2f}/wk):',
                     font=('Segoe UI', 7), fg='#cdd9e5', bg='#161b22',
                     width=30, anchor='w').pack(side='left')
            v = tk.StringVar(value=pl.get(tname,
                                          self.STRIPE_PAYLINK_DEFAULTS.get(tname, '')))
            pl_vars[tname] = v
            tk.Entry(prow, textvariable=v, font=('Segoe UI', 7), width=46,
                     bg='#0d1117', fg='#cdd9e5', insertbackground='#635BFF',
                     relief='flat', highlightbackground='#30363d',
                     highlightthickness=1).pack(side='left', padx=4)
        def _save_links():
            st2 = load_app_settings()
            st2['stripe_paylinks'] = {k: v.get().strip() for k, v in pl_vars.items()
                                      if v.get().strip()}
            save_app_settings(st2)
            messagebox.showinfo('Stripe', 'Payment Links saved.', parent=win)
        tk.Button(sf, text='Save links', font=('Segoe UI', 7, 'bold'),
                  bg='#21262d', fg='#cdd9e5', relief='flat', padx=8, pady=2,
                  cursor='hand2', command=_save_links).pack(anchor='w', padx=8, pady=(2, 0))

        def _sync():
            sync_var.set('Syncing…')
            def _worker():
                ok2, msg2 = self._stripe_sync_subscriptions()
                def _done():
                    if not win.winfo_exists():
                        return
                    if ok2:
                        messagebox.showinfo('Stripe Sync', msg2, parent=win)
                        win.destroy(); self._open_admin_dashboard()
                    else:
                        sync_var.set(f'Sync failed: {msg2}')
                self.after(0, _done)
            threading.Thread(target=_worker, daemon=True).start()
        tk.Button(sf, text='🔄 Sync Subscriptions', font=('Segoe UI', 8, 'bold'),
                  bg='#21262d', fg='#635BFF', relief='flat', padx=10, pady=3,
                  cursor='hand2', command=_sync).pack(anchor='w', padx=8, pady=(2, 2))
        tk.Label(sf, text='Fully Stripe-HOSTED payments: users pay on Stripe\'s own page via the '
                          'links above — no card data or backend on our side. Each opened link '
                          'carries client_reference_id=<K-ID>, which lands on the Checkout '
                          'Session; Sync matches it back and activates the tier. (Webhooks '
                          'would need a public endpoint, hence polling.)',
                 font=('Segoe UI', 7), fg='#8b949e', bg='#161b22',
                 wraplength=800, justify='left').pack(anchor='w', padx=8, pady=(0, 6))

    def _build_rewards_tab(self):
        """💎 Rewards — K-ID reward economy: daily logins, streaks, ad
        rewards, supporter tiers, stake limits, raffle status."""
        tab = self.tab_rewards
        for w in tab.winfo_children():
            w.destroy()
        import datetime as _dt
        BG = '#0d1117'; PANEL = '#161b22'; GOLD = '#FFD700'
        FG = '#cdd9e5'; DIM = '#8b949e'; GREEN = '#3FB950'

        pts = self._pts_load()
        daily_msgs = self._rewards_daily_engine(pts)
        if daily_msgs:
            self._pts_save(pts)
        tier_name = pts.get('tier', 'Free')
        tier = self._pts_tier(pts)

        hdr = tk.Frame(tab, bg=BG); hdr.pack(fill='x', padx=12, pady=(10, 6))
        tk.Label(hdr, text='💎  REWARDS', font=('Segoe UI', 14, 'bold'),
                 fg=GOLD, bg=BG).pack(side='left')
        tk.Label(hdr, text=f'  🆔 {CURRENT_KID or "guest"}   ·   '
                           f'{tier["badge"]} {tier_name}',
                 font=('Segoe UI', 9, 'bold'), fg=tier['color'], bg=BG).pack(side='left')
        tk.Button(hdr, text='💳 Get Credits', font=('Segoe UI', 8, 'bold'),
                  bg='#1a1a2e', fg='#635BFF', relief='flat', padx=10, pady=3,
                  cursor='hand2', command=self._open_credit_buy_popup
                  ).pack(side='left', padx=(14, 0))
        if (CURRENT_KID or '').strip().lower() == ADMIN_KID:
            tk.Button(hdr, text='🛡 Admin Dashboard', font=('Segoe UI', 8, 'bold'),
                      bg='#2a0a0a', fg='#F85149', relief='flat', padx=10, pady=3,
                      cursor='hand2', command=self._open_admin_dashboard
                      ).pack(side='left', padx=(14, 0))
        cr_lbl = tk.Label(hdr, text=f'💰 {pts.get("credits", 0):,.0f} Cr  🧾',
                 font=('Segoe UI', 11, 'bold'), fg=GOLD, bg=BG, cursor='hand2')
        cr_lbl.pack(side='right')
        cr_lbl.bind('<Button-1>', lambda e: self._open_credit_history_popup(pts))

        if daily_msgs:
            ban = tk.Frame(tab, bg='#1a2a0a', highlightbackground=GREEN,
                           highlightthickness=1, padx=12, pady=8)
            ban.pack(fill='x', padx=12, pady=(0, 6))
            tk.Label(ban, text='🎁 TODAY\'S REWARDS CLAIMED', font=('Segoe UI', 8, 'bold'),
                     fg=GREEN, bg='#1a2a0a').pack(anchor='w')
            for m in daily_msgs:
                tk.Label(ban, text=m, font=('Segoe UI', 8), fg=FG,
                         bg='#1a2a0a').pack(anchor='w')

        body = tk.Frame(tab, bg=BG); body.pack(fill='both', expand=True, padx=12, pady=(0, 10))

        # ── Left column: status + ads ──────────────────────────────────────────
        left = tk.Frame(body, bg=PANEL, highlightbackground='#21262d',
                        highlightthickness=1, padx=12, pady=10)
        left.pack(side='left', fill='both', expand=True, padx=(0, 6))

        cyc = pts.get('login_streak_day', 0); run = pts.get('login_streak_len', 0)
        nxt = self.LOGIN_REWARDS[cyc % 7]
        claimed_today = pts.get('login_last_date') == _dt.date.today().isoformat()
        dl_hdr = tk.Frame(left, bg=PANEL); dl_hdr.pack(anchor='w', fill='x')
        tk.Label(dl_hdr, text='📅  DAILY LOGIN', font=('Segoe UI', 10, 'bold'),
                 fg=GOLD, bg=PANEL).pack(side='left')
        tk.Label(dl_hdr, text='✅ Today claimed' if claimed_today else '⏳ Not claimed yet',
                 font=('Segoe UI', 8, 'bold'),
                 fg=GREEN if claimed_today else '#D29922', bg=PANEL
                 ).pack(side='left', padx=(8, 0))
        tk.Label(left, text=f'Cycle day {cyc}/7  ·  streak {run} day(s)\n'
                            f'Tomorrow (Day {(cyc % 7) + 1}): +{nxt:,} Cr'
                            + (f'  (+{self.STREAK_BONUS[run+1]:,} streak bonus)'
                               if (run + 1) in self.STREAK_BONUS else ''),
                 font=('Segoe UI', 8), fg=FG, bg=PANEL, justify='left').pack(anchor='w', pady=(2, 10))

        # ── Weekly credit drip — the supporter tier's daily payout, shown
        # as its weekly total so users can see what the subscription is
        # actually worth (Free has no drip and this section is skipped).
        if tier.get('daily_drip'):
            wk_total = tier['daily_drip'] * 6 + tier['day7_drip']
            today_drip = tier['day7_drip'] if cyc == 7 else tier['daily_drip']
            tk.Label(left, text='🪙  WEEKLY CREDIT DRIP', font=('Segoe UI', 10, 'bold'),
                     fg=GOLD, bg=PANEL).pack(anchor='w')
            tk.Label(left,
                     text=f"{tier['badge']} {tier_name}: +{tier['daily_drip']:,} Cr/day"
                          f" (Day 7: +{tier['day7_drip']:,} Cr)\n"
                          f"Weekly total: {wk_total:,} Cr  ·  "
                          + ("today's drip already paid" if claimed_today
                             else f'today\'s drip: +{today_drip:,} Cr on next open'),
                     font=('Segoe UI', 8), fg=FG, bg=PANEL, justify='left'
                     ).pack(anchor='w', pady=(2, 10))

        tk.Label(left, text='📺  AD REWARDS', font=('Segoe UI', 10, 'bold'),
                 fg=GOLD, bg=PANEL).pack(anchor='w')
        if tier['ads_free']:
            tk.Label(left, text='Ad-free experience — your tier drip replaces ad rewards.',
                     font=('Segoe UI', 8), fg=DIM, bg=PANEL,
                     wraplength=260, justify='left').pack(anchor='w', pady=(2, 10))
        else:
            watched = pts.get('ads_watched', 0)
            tk.Label(left, text=f'{watched}/{self.AD_DAILY_LIMIT} watched today  ·  '
                                f'+{self.AD_REWARD_MIN}–{self.AD_REWARD_MAX} Cr each\n'
                                f'(reward unlocks after {self.AD_VIEW_SECONDS}s view time)',
                     font=('Segoe UI', 8), fg=FG, bg=PANEL, justify='left').pack(anchor='w', pady=2)
            tk.Button(left, text='▶  Watch Ad', command=self._rewards_open_ad_popup,
                      font=('Segoe UI', 9, 'bold'), bg='#21262d', fg=GOLD,
                      relief='flat', padx=12, pady=4, cursor='hand2').pack(anchor='w', pady=(4, 10))

        tk.Label(left, text='🎯  PLAY LIMITS', font=('Segoe UI', 10, 'bold'),
                 fg=GOLD, bg=PANEL).pack(anchor='w')
        tk.Label(left, text=f'Min stake: {self.PTS_MIN_STAKE:,.0f} Cr  ·  '
                            f'Max single play: {self._pts_max_stake(pts):,.0f} Cr\n'
                            f'(applies across PTS, ZDWS and ZDOS)',
                 font=('Segoe UI', 8), fg=FG, bg=PANEL, justify='left').pack(anchor='w', pady=(2, 10))

        tk.Label(left, text='🎟️  RAFFLE', font=('Segoe UI', 10, 'bold'),
                 fg=GOLD, bg=PANEL).pack(anchor='w')
        tk.Label(left, text=self._rewards_raffle_status(pts),
                 font=('Segoe UI', 8), fg=FG, bg=PANEL,
                 wraplength=260, justify='left').pack(anchor='w', pady=2)

        # Draw controls — admin action: runs the cross-wallet draw for each
        # raffle (cadence-guarded, so clicking early just reports next date).
        draw_row = tk.Frame(left, bg=PANEL); draw_row.pack(fill='x', pady=(4, 2))
        for _tname, _cfg in self.RAFFLES.items():
            n_elig = len(self._raffle_entrants(_tname))
            tk.Button(draw_row,
                      text=f'🎲 Draw {_tname} ({n_elig} eligible)',
                      font=('Segoe UI', 7, 'bold'), bg='#21262d', fg=GOLD,
                      relief='flat', padx=6, pady=3, cursor='hand2',
                      command=lambda t=_tname: self._raffle_run_draw(t)
                      ).pack(side='left', padx=(0, 4))

        # Recent winners
        _rh = load_app_settings().get('raffle_history', [])
        if _rh:
            tk.Label(left, text='Recent winners:', font=('Segoe UI', 7, 'bold'),
                     fg=DIM, bg=PANEL).pack(anchor='w', pady=(4, 0))
            for h in _rh[-4:][::-1]:
                tk.Label(left,
                         text=f"{h['date']}  {h['tier']}: {h['winner']} — {h['prize']}",
                         font=('Segoe UI', 7), fg=FG, bg=PANEL,
                         wraplength=260, justify='left').pack(anchor='w')

        # ── SoR mode — per-K-ID, not admin-gated: Default is automatically
        #    active the moment this K-ID is valid; Custom must be switched
        #    on by the user themselves. ─────────────────────────────────────
        tk.Label(left, text='🎁  SoR MODE', font=('Segoe UI', 10, 'bold'),
                 fg=GOLD, bg=PANEL).pack(anchor='w', pady=(10, 0))
        custom_on = bool(pts.get('sor_custom_enabled'))
        _sor_cfg = self._sor_config()
        if custom_on:
            _y = pts.get('sor_custom_threshold') or _sor_cfg['custom_threshold']
            if (CURRENT_KID or '').strip().lower() == ADMIN_KID:
                _mode_desc = (f"Custom — {_sor_cfg.get('custom_credits', 1):g} Cr (admin-locked) "
                               f"per {_y:g} units held (your own Y, any market).")
            else:
                _mode_desc = (f"Custom — your rate: {_y:g} units per credit "
                               f"(credit amount set by admin, any market).")
        else:
            _mode_desc = (f"Default — active for any signed-in K-ID. Min units to earn: "
                           f"MY {_sor_cfg['my_min_units']:g}  ·  US {_sor_cfg['us_min_units']:g}")
        tk.Label(left, text=_mode_desc,
                 font=('Segoe UI', 8), fg=FG, bg=PANEL,
                 wraplength=260, justify='left').pack(anchor='w', pady=2)
        tk.Button(left, text=('↩ Switch back to Default' if custom_on else '⚙ Switch to Custom'),
                  font=('Segoe UI', 7, 'bold'), bg='#21262d', fg=GOLD,
                  relief='flat', padx=6, pady=3, cursor='hand2',
                  command=self._rewards_toggle_sor_mode).pack(anchor='w', pady=(2, 0))

        # ── Right column: supporter tiers ──────────────────────────────────────
        right = tk.Frame(body, bg=BG); right.pack(side='left', fill='both', expand=True)
        tk.Label(right, text='☕  KOFI SUPPORTER TIERS   ·   payment via KoFi/Stripe '
                             'happens outside the app — activate here once confirmed',
                 font=('Segoe UI', 8, 'bold'), fg=DIM, bg=BG,
                 wraplength=420, justify='left').pack(anchor='w', pady=(0, 4))
        for name, t in self.PAA_TIERS.items():
            card = tk.Frame(right, bg=PANEL,
                            highlightbackground=t['color'] if name == tier_name else '#21262d',
                            highlightthickness=2 if name == tier_name else 1,
                            padx=10, pady=6)
            card.pack(fill='x', pady=3)
            row = tk.Frame(card, bg=PANEL); row.pack(fill='x')
            tk.Label(row, text=f"{t['badge']} {name}", font=('Segoe UI', 9, 'bold'),
                     fg=t['color'], bg=PANEL).pack(side='left')
            tk.Label(row, text=('  · current' if name == tier_name else ''),
                     font=('Segoe UI', 8), fg=GREEN, bg=PANEL).pack(side='left')
            if name != tier_name:
                _is_admin = (CURRENT_KID or '').strip().lower() == ADMIN_KID
                if name == 'Free':
                    # Reflect a cancel locally right away (billing itself is
                    # cancelled on Stripe's hosted portal / dashboard).
                    tk.Button(row, text='Downgrade', font=('Segoe UI', 7, 'bold'),
                              bg='#21262d', fg=FG, relief='flat', padx=8, cursor='hand2',
                              command=lambda n=name: (self._rewards_set_tier(n),
                                                      self._build_rewards_tab())
                              ).pack(side='right')
                else:
                    # Hosted payment path for everyone…
                    tk.Button(row, text='💳 Subscribe', font=('Segoe UI', 7, 'bold'),
                              bg='#1a1a2e', fg='#635BFF', relief='flat', padx=8,
                              cursor='hand2',
                              command=lambda n=name: self._rewards_open_subscribe(n)
                              ).pack(side='right')
                    # …manual set is an ADMIN tool only (comping a tier /
                    # fixing a mismatch), so free self-upgrades aren't possible.
                    if _is_admin:
                        tk.Button(row, text='set', font=('Segoe UI', 7),
                                  bg='#21262d', fg='#8b949e', relief='flat', padx=6,
                                  cursor='hand2',
                                  command=lambda n=name: (self._rewards_set_tier(n),
                                                          self._build_rewards_tab())
                                  ).pack(side='right', padx=(0, 4))
            wk = (t['daily_drip'] * 6 + t['day7_drip'])
            desc = (f"RM{t['price_wk']:.2f}/wk  ·  {wk:,} Cr/week"
                    f"  ·  max play {t['max_stake']:,}"
                    + ('  ·  ads-free' if t['ads_free'] else '')
                    + (f"  ·  🎟️ {t['raffle']}" if t['raffle'] else '')) \
                   if name != 'Free' else \
                   (f"Free  ·  logins + ads only  ·  max play {t['max_stake']:,}")
            tk.Label(card, text=desc, font=('Segoe UI', 8), fg=FG, bg=PANEL,
                     wraplength=420, justify='left').pack(anchor='w', pady=(2, 0))
            if name == tier_name and name != 'Free':
                tk.Label(card, text=f'Active {self._rewards_tier_weeks(pts):.1f} week(s)',
                         font=('Segoe UI', 7), fg=DIM, bg=PANEL).pack(anchor='w')

        # ── Embedded ad area (bottom strip) ────────────────────────────────────
        # Inline WebView via tkinterweb when installed; otherwise a styled
        # placeholder with the install hint. Supporters are ads-free, so the
        # strip is simply omitted for them.
        if not tier['ads_free']:
            ad_area = tk.Frame(tab, bg='#161b22', highlightbackground='#30363d',
                               highlightthickness=1)
            ad_area.pack(fill='x', side='bottom', padx=12, pady=(0, 10))
            tk.Label(ad_area, text='SPONSORED', font=('Segoe UI', 6, 'bold'),
                     fg='#8b949e', bg='#161b22').pack(anchor='w', padx=6, pady=(3, 0))
            if _HAS_TKINTERWEB:
                try:
                    hf = _AdHtmlFrame(ad_area, messages_enabled=False, height=120)
                    hf.load_url(self._rewards_ad_page())
                    hf.pack(fill='x', padx=6, pady=(0, 4))
                except Exception:
                    tk.Label(ad_area, text='Ad area — failed to render page',
                             font=('Segoe UI', 8), fg='#8b949e',
                             bg='#161b22', pady=18).pack(fill='x')
            else:
                tk.Label(ad_area,
                         text='Ad area — install tkinterweb to render inline\n'
                              '(pip install tkinterweb)  ·  the ▶ Watch Ad popup works either way',
                         font=('Segoe UI', 8), fg='#8b949e', bg='#161b22',
                         justify='center', pady=18).pack(fill='x')

    PTS_TRADE_LOT        = 10_000.0   # lot size reference from proposal

    # ── Category definitions ──────────────────────────────────────────────────
    PTS_CATEGORIES = [
        'Stock Price Target',
        'Index Target',
        'IPO Performance',
        'Economic Forecast',
        'Custom',
    ]

    def _pts_load(self) -> dict:
        """Load THIS K-ID's PTS/ZDWS wallet from paa_settings.json.

        Storage: settings['pts_by_user'][username]  — one wallet per K-ID, so
        credits, predictions and warrants never leak between accounts.
        Legacy global settings['pts'] is migrated to the current user on first
        read, then left in place as a dormant backup.
        """
        s   = load_app_settings()
        key = (CURRENT_KID or '').strip().lower()   # '' = guest / legacy PIN mode
        presence_touch()   # keep the online heartbeat fresh (60s throttle inside)

        by_user = s.setdefault('pts_by_user', {})

        if key not in by_user:
            legacy = s.get('pts')
            # Migrate the old global wallet to the first K-ID that signs in,
            # but only if it actually holds something worth keeping.
            if legacy and not s.get('pts_migrated') and (
                legacy.get('predictions') or legacy.get('history')
                or legacy.get('zdws_active') or legacy.get('zdws_history')
                or legacy.get('credits', 0) != _DEFAULT_SETTINGS['pts']['credits']
            ):
                by_user[key]      = dict(legacy)
                s['pts_migrated'] = True
                save_app_settings(s)
            else:
                by_user[key] = _pts_fresh_wallet()
                save_app_settings(s)

        pts = by_user[key]
        for k, v in _DEFAULT_SETTINGS['pts'].items():
            # deep-copy mutable defaults so wallets never share list objects
            pts.setdefault(k, _copy.deepcopy(v) if isinstance(v, (list, dict)) else v)
        return pts

    def _pts_save(self, pts: dict):
        """Persist THIS K-ID's PTS/ZDWS wallet."""
        s   = load_app_settings()
        key = (CURRENT_KID or '').strip().lower()
        s.setdefault('pts_by_user', {})[key] = pts
        save_app_settings(s)

    def _pts_rank(self, pts: dict) -> tuple:
        """Return (rank_label, rank_color) based on accuracy and prediction count."""
        total   = pts.get('total_made', 0)
        correct = pts.get('total_correct', 0)
        acc     = (correct / total * 100) if total else 0
        for min_acc, min_preds, label, color in self.PTS_RANKS:
            if acc >= min_acc and total >= min_preds:
                return label, color
        return self.PTS_RANKS[-1][2], self.PTS_RANKS[-1][3]

    # =========================================================================
    # ZDWS — Zero-Decay Warrant System
    # Bull/Bear warrants on internal indices. P/L = stake × (1 + |%move| × 10)
    # if direction correct, 0 if wrong. Zero time decay. Auto-settles when the
    # settlement date passes (checked on every PTS tab refresh).
    # =========================================================================

    # ── World indices tradeable via ZDWS ──────────────────────────────────────
    # Credits are MYR-denominated, so a foreign index bet is settled on the
    # MYR-converted move: total% = index% + FX%. That is what a Malaysian
    # investor actually experiences, and it makes an HKD and a USD position
    # comparable from the same wallet.
    WORLD_INDICES = [
        ('^HSI',  'Hang Seng',       'HKD'),
        ('^STI',  'Straits Times',   'SGD'),
        ('^N225', 'Nikkei 225',      'JPY'),
        ('^KS11', 'KOSPI',           'KRW'),
        ('^TWII', 'Taiwan Weighted', 'TWD'),
        ('^GSPC', 'S&P 500',         'USD'),
        ('^IXIC', 'Nasdaq Composite','USD'),
        ('^DJI',  'Dow Jones',       'USD'),
        ('^SOX',  'PHLX Semiconductor','USD'),
        ('^RUI',  'Russell 1000',    'USD'),
        ('^RUT',  'Russell 2000',    'USD'),
        ('^RUA',  'Russell 3000',    'USD'),
        ('^FTSE', 'FTSE 100',        'GBP'),
        ('^FTMC', 'FTSE 250',        'GBP'),
        # S&P Select Sector indices — Yahoo lists these under either an
        # ^IXxx or ^SIXxx symbol depending on the sector, so the fetch
        # layer (_fetch, below) tries both prefixes for every one of these.
        ('^IXT',   'S&P Technology Select Sector',              'USD'),
        ('^IXF',   'S&P Financial Select Sector',                'USD'),
        ('^IXV',   'S&P Health Care Select Sector',               'USD'),
        ('^IXY',   'S&P Consumer Discretionary Select Sector',    'USD'),
        ('^IXR',   'S&P Consumer Staples Select Sector',          'USD'),
        ('^IXI',   'S&P Industrials Select Sector',                'USD'),
        ('^IXE',   'S&P Energy Select Sector',                    'USD'),
        ('^IXU',   'S&P Utilities Select Sector',                 'USD'),
        ('^IXB',   'S&P Materials Select Sector',                 'USD'),
        ('^IXC',   'S&P Communication Services Select Sector',    'USD'),
        ('^SIXRE', 'S&P Real Estate Select Sector',                'USD'),
        # Major Australian indices — all Yahoo-verified symbols.
        ('^AFLI', 'S&P/ASX 50',   'AUD'),
        ('^ATOI', 'S&P/ASX 100',  'AUD'),
        ('^AXJO', 'S&P/ASX 200',  'AUD'),
    ]

    # Marquee-only major FX crosses — deliberately NOT part of WORLD_INDICES,
    # since that table drives index matching/ZDWS/ZDOS elsewhere and these
    # are currency pairs, not indices. (sym, label, yahoo_sym)
    MAJOR_FX_PAIRS = [
        ('FXM:EURUSD', 'EUR/USD', 'EURUSD=X'),
        ('FXM:GBPUSD', 'GBP/USD', 'GBPUSD=X'),
        ('FXM:USDCAD', 'USD/CAD', 'USDCAD=X'),
        ('FXM:USDSGD', 'USD/SGD', 'USDSGD=X'),
        ('FXM:USDJPY', 'USD/JPY', 'USDJPY=X'),
        ('FXM:AUDUSD', 'AUD/USD', 'AUDUSD=X'),
        ('FXM:NZDUSD', 'NZD/USD', 'NZDUSD=X'),
    ]
    # Low-value currencies shown per-N-units on the marquee (e.g. "100JPY=")
    # instead of the raw per-1-unit rate, which would round to ~0.0000.
    _FX_DISPLAY_SCALE = {'JPY': 100, 'KRW': 1000, 'IDR': 10000}
    # Currencies people want an MYR pair for even without a matching index —
    # AUD/MYR now comes free via the ASX indices above; THB/MYR (common for
    # Malaysians saving/accumulating toward a Thailand trip) has no index of
    # its own, so it's added here explicitly.
    _EXTRA_FX_CCYS = ('THB',)

    def _fx_display_label(self, ccy: str) -> str:
        scale = self._FX_DISPLAY_SCALE.get(ccy)
        if not scale:
            return f'{ccy}MYR'
        n = f'{scale // 1000}K' if scale >= 1000 else str(scale)
        return f'{n}{ccy}='

    def _fx_ccys(self) -> list:
        """All currencies that get an MYR marquee line: every WORLD_INDICES
        currency plus the explicit travel-savings extras (THB etc.)."""
        return sorted({c for _, _, c in self.WORLD_INDICES if c != 'MYR'}
                      | set(self._EXTRA_FX_CCYS))

