    def _opie_chat_submit(self, entry_widget):
        """Handle whatever was typed into the OPIE chat box. Only greeting
        phrases trigger a reply — anything else is quietly ignored so the
        box doesn't feel like a black hole, but also isn't a real chatbot."""
        text = entry_widget.get().strip()
        if not text or text == 'Type: Hi, Opie':
            return
        greeting = text.lower().replace(',', '').replace('!', '').strip()
        if greeting in _OPIE_GREETINGS:
            self._opie_reply_var.set(self._opie_lightweight_summary())
            self._opie_reply_row.pack(fill='x', padx=0, pady=(0, 4), after=self.winfo_children()[0])
        else:
            self._opie_reply_var.set("Try: \"Hi, Opie\" for a quick portfolio summary.")
            self._opie_reply_row.pack(fill='x', padx=0, pady=(0, 4), after=self.winfo_children()[0])
        entry_widget.delete(0, 'end')
        self.focus_set()

    def _opie_lightweight_summary(self) -> str:
        """Self-contained portfolio summary — no OPIE module dependency.
        Reads whatever SCA already has loaded: position count, diversification
        (same buckets OPIE used to report), and real value/return figures
        OPIE itself never actually computed, converted into the forced base
        currency so nothing gets mixed across MYR/USD."""
        portfolios = self._portfolios or {}
        if not portfolios:
            return "Hi! No portfolio loaded yet — connect a source first."

        base_ccy = getattr(self, '_pchart_base_ccy', None)
        ccy_counts = {}
        for port in portfolios.values():
            c = port.get('base_currency', 'USD')
            ccy_counts[c] = ccy_counts.get(c, 0) + 1
        if not base_ccy:
            base_ccy = get_home_currency() if ccy_counts else 'MYR'
        fx = self._fx_rates or {getattr(self, '_fx_home', get_home_currency()): 1.0}
        prefix = ccy_symbol(base_ccy)

        def _to_base(amount, ccy):
            if ccy == base_ccy:
                return amount
            # Pivot is whichever currency fx[] is keyed against (home
            # currency) — works regardless of what that home currency is,
            # not just when it happens to be MYR.
            amount_pivot = amount * fx.get(ccy, 1.0)
            return amount_pivot / fx.get(base_ccy, 1.0)

        positions   = 0
        cost_total  = 0.0
        mv_total    = 0.0
        price_data  = getattr(self, '_last_price_data', {})
        for port in portfolios.values():
            ccy = port.get('base_currency', 'USD')
            for ticker, item in port.get('holdings', {}).items():
                if item.get('_is_cash'):
                    continue
                shares = item.get('shares', 0)
                if not shares or shares <= 0:
                    continue
                positions  += 1
                cost_total += _to_base(item.get('cost_value', 0.0), ccy)
                p = price_data.get(ticker)
                mv_total += _to_base(shares * p, ccy) if p else _to_base(item.get('cost_value', 0.0), ccy)

        diversification = ('not available' if not positions else
                            'concentrated' if positions < 4 else
                            'developing' if positions < 8 else 'diversified')
        ret_val = mv_total - cost_total
        ret_pct = (ret_val / cost_total * 100) if cost_total > 0 else 0.0

        return (f"{positions} active position(s), diversification is {diversification} "
                f"({len(ccy_counts)} currency source(s), forced to {base_ccy}). "
                f"Value: {prefix}{mv_total:,.2f} | "
                f"Unrealized: {prefix}{ret_val:+,.2f} ({ret_pct:+.2f}%).")

    # ─────────────────────────────────────────────────────────────────────────
    # SCAIE — Indirect Exposure (via ETFs held, US market only)
    # Reuses the alpha.102 ETF Top-10 Holdings pipeline (_opie_fetch_etf_holdings)
    # that OPIE's chat used to reach — but OPIE-the-agent is disabled and never
    # answers this, so it's exposed here directly as its own SCA button instead.
    # For every US-market ETF/fund actually held: units held × live price ×
    # each underlying's holding % = that underlying's look-through $ exposure.
    # Exposure to the same underlying through multiple ETFs is summed.
    # ─────────────────────────────────────────────────────────────────────────
    def _open_sca_ie(self):
        portfolios = self._portfolios or {}
        if not portfolios:
            messagebox.showinfo('SCAIE', 'No portfolio loaded yet.', parent=self)
            return

        price_data = getattr(self, '_last_price_data', {})
        exposure, etfs_used, etf_mv_total = _opie_compute_indirect_exposure(
            portfolios, price_data)

        if not etfs_used:
            messagebox.showinfo(
                'SCAIE',
                "No US-market ETFs/funds detected among your holdings\n"
                "(or their Top-10 holdings couldn't be fetched — try ↻ Refresh first).",
                parent=self)
            return

        self._render_sca_ie_window(exposure, etfs_used, etf_mv_total)

    def _render_sca_ie_window(self, exposure: dict, etfs_used: list, etf_mv_total: float):
        win = tk.Toplevel(self)
        win.title('SCAIE — Indirect Exposure')
        win.configure(bg=self.BG)
        win.geometry('580x560')
        win.minsize(480, 360)
        win.transient(self)

        top_row = tk.Frame(win, bg=self.BG)
        top_row.pack(fill='x', padx=16, pady=(14, 2))
        tk.Label(top_row, text='SCAIE — Indirect Exposure (via ETFs · US)',
                 font=('Courier New', 12, 'bold'), fg=self.TEAL, bg=self.BG
                 ).pack(side='left')

        mode_var = tk.StringVar(value='detail')

        def _redraw():
            for w in body.winfo_children():
                w.destroy()
            if mode_var.get() == 'summary':
                summary_txt = _opie_format_indirect_exposure_summary(
                    exposure, etfs_used, etf_mv_total)
                tk.Label(body, text=summary_txt, font=('Courier New', 9),
                         fg=self.FG, bg=self.PANEL, wraplength=520,
                         justify='left', anchor='nw').pack(fill='both',
                         expand=True, padx=14, pady=14)
            elif mode_var.get() == 'fallers':
                self._build_sca_ie_movers_table(body, exposure, worst=True)
            elif mode_var.get() == 'uppers':
                self._build_sca_ie_movers_table(body, exposure, worst=False)
            else:
                self._build_sca_ie_table(body, exposure, etf_mv_total)

        toggle_btn = tk.Button(top_row, font=self.FONT_B, bg='#1a2035', fg=self.TEAL,
                                relief='flat', padx=8, pady=3, cursor='hand2')
        def _toggle():
            # Cycles: detail -> summary -> fallers -> uppers -> detail
            order = ['detail', 'summary', 'fallers', 'uppers']
            nxt = order[(order.index(mode_var.get()) + 1) % len(order)]
            mode_var.set(nxt)
            toggle_btn.config(text={'detail': '📊 Total Exposure',
                                     'summary': '🔻 Biggest Fallers',
                                     'fallers': '🚀 Biggest Uppers',
                                     'uppers': '📋 Detailed'}[nxt])
            _redraw()
        toggle_btn.config(text='📊 Total Exposure', command=_toggle)
        toggle_btn.pack(side='right')

        tk.Label(win,
                 text=f"Look-through exposure from {len(etfs_used)} ETF(s) held: "
                      f"{', '.join(etfs_used)}",
                 font=('Courier New', 8), fg=self.FG2, bg=self.BG,
                 wraplength=540, justify='left').pack(padx=16, pady=(0, 10))

        body = tk.Frame(win, bg=self.PANEL, highlightbackground=self.BORDER,
                         highlightthickness=1)
        body.pack(fill='both', expand=True, padx=16, pady=(0, 6))

        _redraw()

        tk.Label(win,
            text=(f"Total ETF market value: ${etf_mv_total:,.2f}   ·   "
                  f"Top-10 holdings per ETF only (yfinance funds_data, cached 24h) "
                  f"— real look-through exposure may be broader."),
            font=('Courier New', 7), fg=self.DIM, bg=self.BG,
            wraplength=540, justify='left').pack(padx=16, pady=(4, 12))

    def _build_sca_ie_table(self, body, exposure: dict, etf_mv_total: float):
        """Detailed per-underlying table — original SCAIE view, factored out
        so the 📊 Total Exposure toggle can swap it for the simplified
        narrative summary without rebuilding the whole window."""
        hdr = tk.Frame(body, bg=self.PANEL)
        hdr.pack(fill='x', padx=8, pady=(8, 4))
        for text, w, anchor in (('Underlying', 26, 'w'), ('Via', 14, 'w'),
                                 ('$ Exposure', 12, 'e'), ('% of ETF MV', 11, 'e')):
            tk.Label(hdr, text=text, font=self.FONT_B, fg=self.FG2, bg=self.PANEL,
                     width=w, anchor=anchor).pack(side='left')

        canvas = tk.Canvas(body, bg=self.PANEL, highlightthickness=0)
        vbar = ttk.Scrollbar(body, orient='vertical', command=canvas.yview)
        canvas.configure(yscrollcommand=vbar.set)
        vbar.pack(side='right', fill='y')
        canvas.pack(side='left', fill='both', expand=True)
        rows_frame = tk.Frame(canvas, bg=self.PANEL)
        canvas.create_window((0, 0), window=rows_frame, anchor='nw')
        rows_frame.bind('<Configure>',
            lambda e: canvas.configure(scrollregion=canvas.bbox('all')))
        canvas.bind('<MouseWheel>',
            lambda e: canvas.yview_scroll(int(-e.delta / 120), 'units'))

        ranked = sorted(exposure.items(), key=lambda kv: kv[1]['value'], reverse=True)
        for sym, rec in ranked:
            row = tk.Frame(rows_frame, bg=self.PANEL)
            row.pack(fill='x', padx=8, pady=1)
            name = rec.get('name') or sym
            label = f"{sym} — {name}" if name != sym else sym
            tk.Label(row, text=label[:26], font=self.FONT, fg=self.FG, bg=self.PANEL,
                     width=26, anchor='w').pack(side='left')
            tk.Label(row, text=', '.join(sorted(rec['via']))[:14], font=self.FONT,
                     fg=self.FG2, bg=self.PANEL, width=14, anchor='w').pack(side='left')
            tk.Label(row, text=f"${rec['value']:,.2f}", font=self.FONT,
                     fg=self.GREEN, bg=self.PANEL, width=12, anchor='e').pack(side='left')
            pct = (rec['value'] / etf_mv_total * 100) if etf_mv_total else 0.0
            tk.Label(row, text=f"{pct:.2f}%", font=self.FONT, fg=self.FG2,
                     bg=self.PANEL, width=11, anchor='e').pack(side='left')

        if not ranked:
            tk.Label(rows_frame, text='No underlying holdings data available.',
                     font=self.FONT, fg=self.DIM, bg=self.PANEL).pack(pady=10)

    def _build_sca_ie_movers_table(self, body, exposure: dict, worst: bool = True):
        """'🔻 Biggest Fallers' / '🚀 Biggest Uppers' — of everything you're
        indirectly exposed to through ETFs, which underlyings actually
        moved the most today. Ranks by day-change %, not $ exposure — a
        name can be a small slice of your portfolio and still be the
        thing dragging on (or driving) performance today. worst=True ->
        fallers (ascending, biggest decline first); worst=False -> uppers
        (descending, biggest gain first)."""
        hdr = tk.Frame(body, bg=self.PANEL)
        hdr.pack(fill='x', padx=8, pady=(8, 4))
        for text, w, anchor in (('Underlying', 26, 'w'), ('Via', 14, 'w'),
                                 ('Day Δ', 10, 'e'), ('$ Exposure', 12, 'e')):
            tk.Label(hdr, text=text, font=self.FONT_B, fg=self.FG2, bg=self.PANEL,
                     width=w, anchor=anchor).pack(side='left')

        tk.Label(body, text='Fetching today\'s move for each underlying…',
                 font=self.FONT, fg=self.DIM, bg=self.PANEL).pack(pady=10)
        body.update_idletasks()

        # Only fetch for the top-20-by-exposure names — a full per-symbol
        # fetch across every underlying in every ETF held would be slow and
        # mostly noise (a 0.01%-weight underlying moving isn't a "mover"
        # that matters to this portfolio).
        by_exposure = sorted(exposure.items(), key=lambda kv: kv[1]['value'], reverse=True)
        top_syms = [sym for sym, _ in by_exposure[:20]]
        day_chg = _opie_fetch_underlying_day_change(top_syms)

        for w in body.winfo_children():
            if isinstance(w, tk.Label) and 'Fetching' in str(w.cget('text')):
                w.destroy()

        ranked = sorted(
            ((sym, rec, day_chg[sym]) for sym, rec in by_exposure if sym in day_chg),
            key=lambda t: t[2], reverse=not worst
        )

        canvas = tk.Canvas(body, bg=self.PANEL, highlightthickness=0)
        vbar = ttk.Scrollbar(body, orient='vertical', command=canvas.yview)
        canvas.configure(yscrollcommand=vbar.set)
        vbar.pack(side='right', fill='y')
        canvas.pack(side='left', fill='both', expand=True)
        rows_frame = tk.Frame(canvas, bg=self.PANEL)
        canvas.create_window((0, 0), window=rows_frame, anchor='nw')
        rows_frame.bind('<Configure>',
            lambda e: canvas.configure(scrollregion=canvas.bbox('all')))
        canvas.bind('<MouseWheel>',
            lambda e: canvas.yview_scroll(int(-e.delta / 120), 'units'))

        for sym, rec, chg in ranked:
            row = tk.Frame(rows_frame, bg=self.PANEL)
            row.pack(fill='x', padx=8, pady=1)
            name = rec.get('name') or sym
            label = f"{sym} — {name}" if name != sym else sym
            tk.Label(row, text=label[:26], font=self.FONT, fg=self.FG, bg=self.PANEL,
                     width=26, anchor='w').pack(side='left')
            tk.Label(row, text=', '.join(sorted(rec['via']))[:14], font=self.FONT,
                     fg=self.FG2, bg=self.PANEL, width=14, anchor='w').pack(side='left')
            chg_color = self.GREEN if chg >= 0 else (self.RED if hasattr(self, 'RED') else '#ff6b6b')
            tk.Label(row, text=f"{chg:+.2f}%", font=self.FONT, fg=chg_color,
                     bg=self.PANEL, width=10, anchor='e').pack(side='left')
            tk.Label(row, text=f"${rec['value']:,.2f}", font=self.FONT,
                     fg=self.FG2, bg=self.PANEL, width=12, anchor='e').pack(side='left')

        if not ranked:
            tk.Label(rows_frame, text='Could not fetch day-change data for these underlyings.',
                     font=self.FONT, fg=self.DIM, bg=self.PANEL).pack(pady=10)

    def _open_sor_settings(self):
        """🎁 SoR Settings — admin-tunable Save-for-Rewards rates, kept here
        in SCA since this is where saved holdings (the SoR input) live.
        Two modes: Default (preset per-region rates, gated by a minimum
        holding) or Custom (one flat units-per-Cr rule for everything).
        Also links straight into this K-ID's SoR-tagged credit history so
        rate changes can be checked against real payout events."""
        if (CURRENT_KID or '').strip().lower() != ADMIN_KID:
            messagebox.showwarning('SoR Settings', 'Admin access only.', parent=self)
            return
        app = self.master
        cfg = app._sor_config()

        win = tk.Toplevel(self)
        win.title('🎁 SoR Settings')
        win.configure(bg=self.BG)
        win.geometry('460x600')
        win.transient(self); win.grab_set()

        tk.Label(win, text='🎁  SAVE FOR REWARDS (SoR) — RATES',
                 font=('Courier New', 12, 'bold'), fg=self.TEAL, bg=self.BG).pack(pady=(14, 2))
        tk.Label(win, text='Changes apply to the next SoR run (once per calendar day).',
                 font=('Courier New', 7), fg=self.DIM, bg=self.BG).pack(pady=(0, 10))

        body = tk.Frame(win, bg=self.BG); body.pack(fill='both', expand=True, padx=16)

        # ── Mode note ─────────────────────────────────────────────────────
        # Mode itself is no longer a global admin switch — Default is the
        # automatic baseline the moment a K-ID is valid/signed in, and
        # Custom only ever kicks in for a K-ID that has explicitly turned
        # it on for themselves (⚙ SoR Mode, in the Rewards tab). What's
        # tunable here is just the RATES each mode uses when active.
        tk.Label(body, text='ℹ️  Default mode is always-on automatically for every '
                            'valid K-ID. Custom mode only applies to a K-ID that has '
                            'switched it on themselves (⚙ SoR Mode, Rewards tab). '
                            'The rates below apply whichever mode a given K-ID is in.',
                 font=('Courier New', 7), fg=self.DIM, bg=self.BG,
                 wraplength=400, justify='left').pack(anchor='w', pady=(0, 10))

        default_fields = [
            ('my_min_units',         'MY (Lotto33 + all MY stocks): min units to earn'),
            ('us_min_units',         'US stocks/ETFs: min units to earn'),
            ('us_share_per_cr',      'US: shares per 1 Cr'),
            ('my_lotto_cr_per_unit', 'MY StockLotto33: Cr per unit'),
            ('my_stock_per_cr',      'MY non-Lotto33 stocks: Cr per unit'),
        ]
        custom_fields = [
            ('custom_threshold',     'Custom mode: Y — units per credit (user-adjustable default)'),
            ('custom_credits',       'Custom mode: X — Cr per Y units (ADMIN-LOCKED base unit)'),
        ]
        shared_fields = [
            ('fep_multiplier',       'Beta Supporter (FEP) multiplier'),
            ('supporter_multiplier', 'Other paid tiers multiplier'),
        ]

        entries = {}
        row_widgets = {}

        def _add_field(key, label):
            row = tk.Frame(body, bg=self.BG); row.pack(fill='x', pady=4)
            lbl = tk.Label(row, text=label, font=self.FONT, fg=self.FG, bg=self.BG,
                           width=30, anchor='w')
            lbl.pack(side='left')
            var = tk.StringVar(value=str(cfg.get(key, '')))
            ent = tk.Entry(row, textvariable=var, font=self.FONT, width=10,
                            bg=self.PANEL, fg=self.FG, insertbackground=self.FG,
                            relief='flat')
            ent.pack(side='left')
            entries[key] = var
            row_widgets[key] = (row, lbl, ent)

        tk.Label(body, text='— Default mode rates —', font=('Courier New', 8, 'bold'),
                 fg=self.GOLD, bg=self.BG).pack(anchor='w', pady=(4, 0))
        for key, label in default_fields:
            _add_field(key, label)

        tk.Label(body, text='— Custom mode rate —', font=('Courier New', 8, 'bold'),
                 fg=self.GOLD, bg=self.BG).pack(anchor='w', pady=(10, 0))
        for key, label in custom_fields:
            _add_field(key, label)

        tk.Label(body, text='— Supporter multipliers (both modes) —',
                 font=('Courier New', 8, 'bold'), fg=self.GOLD, bg=self.BG
                 ).pack(anchor='w', pady=(10, 0))
        for key, label in shared_fields:
            _add_field(key, label)

        tk.Label(body, text='Road to Reward thresholds (% saved → bonus Cr) are '
                             'a separate diversification bonus, untouched by mode — '
                             'still kept at built-in defaults; edit paa_settings.json '
                             '"sor_config.road_thresholds" directly for finer control.',
                 font=('Courier New', 7), fg=self.DIM, bg=self.BG,
                 wraplength=400, justify='left').pack(anchor='w', pady=(12, 0))

        status_lbl = tk.Label(win, text='', font=self.FONT, bg=self.BG)
        status_lbl.pack(pady=(4, 0))

        def _save():
            new_cfg = dict(cfg)
            try:
                for key, _ in default_fields + custom_fields + shared_fields:
                    new_cfg[key] = float(entries[key].get())
            except ValueError:
                status_lbl.config(text='All rates must be numbers.', fg=self.RED)
                return
            app._sor_save_config(new_cfg)
            status_lbl.config(text='✓ Saved.', fg=self.GREEN)

        btn_row = tk.Frame(win, bg=self.BG); btn_row.pack(fill='x', padx=16, pady=(10, 6))
        tk.Button(btn_row, text='💾 Save', command=_save, bg='#00e676', fg='#0a0e1a',
                  relief='flat', padx=12, pady=4, cursor='hand2',
                  font=('Courier New', 9, 'bold')).pack(side='left')
        tk.Button(btn_row, text='🧾 View My SoR Credit History',
                  command=lambda: app._open_credit_history_popup(app._pts_load()),
                  bg='#1a2035', fg='#FFD700', relief='flat', padx=12, pady=4,
                  cursor='hand2', font=self.FONT).pack(side='left', padx=(8, 0))

        def _force_rerun():
            # Testing aid: SoR pays at most once per calendar day per K-ID
            # (pts['sor_last_date']). If it already ran today — e.g. while
            # your saved portfolio data was wrong/duplicated — every retry
            # today silently no-ops even after you fix the data. This
            # clears today's gate for THIS K-ID only and re-runs SoR
            # immediately, so you don't have to wait until tomorrow.
            pts = app._pts_load()
            pts['sor_last_date'] = ''
            app._pts_save(pts)
            app._sor_run_and_popup()
            status_lbl.config(text='✓ Re-ran SoR for today.', fg=self.GREEN)
        tk.Button(btn_row, text='🔁 Force Re-run SoR (today)', command=_force_rerun,
                  bg='#2a0a0a', fg='#F85149', relief='flat', padx=12, pady=4,
                  cursor='hand2', font=self.FONT).pack(side='left', padx=(8, 0))

    def _refresh_source_label(self):
        try:
            src = sca_get_source(load_app_settings())
            who = CURRENT_KID or 'guest'
            icon = {'sheet': '📗', 'csv': '📄'}.get(src.get('mode'), '●')
            label = src.get('label', '')
            # The stored label's txn count is a snapshot from whenever the
            # source was last (re)connected — swap in the LIVE row count so
            # this doesn't go stale between reconnects (auto-refresh updates
            # self._rows every 60s, but never touched this label before).
            live_n = len(self._rows or [])
            if live_n and '(' in label and 'txns)' in label:
                label = label.split('(')[0].rstrip() + f' ({live_n} txns)'
            self._src_var.set(f'{icon} {who} · {label}')
        except Exception:
            self._src_var.set('')

    def _open_home_ccy_dialog(self):
        """Set the Home Currency every SCA total/chart converts into.
        Same setting as the dashboard's ⚙ Settings — shared across both."""
        win = tk.Toplevel(self)
        win.title('SCA — Home Currency')
        win.configure(bg=self.BG)
        win.geometry('360x260')
        win.resizable(False, False)
        win.transient(self)
        win.grab_set()

        tk.Label(win, text='💱  HOME CURRENCY', font=('Consolas', 13, 'bold'),
                 fg='#D29922', bg=self.BG).pack(pady=(18, 6))
        tk.Label(win,
                 text='Every SCA total, chart and Cash Ratio converts into\n'
                      'this currency. FX comes from Yahoo Finance live rates,\n'
                      'or from your ledger\'s own FX Rate column (Col I) when\n'
                      'you supply one — that value takes priority.\n'
                      'Applies to Deposit / Withdraw rows only.',
                 font=('Consolas', 8), fg=self.DIM, bg=self.BG,
                 justify='center', wraplength=320).pack(pady=(0, 14))

        home_var = tk.StringVar(value=get_home_currency())
        row = tk.Frame(win, bg=self.BG)
        row.pack()
        for _ccy in _SUPPORTED_HOME_CCYS:
            tk.Radiobutton(row, text=_ccy, variable=home_var, value=_ccy,
                           font=('Consolas', 10), fg=self.FG, bg=self.BG,
                           selectcolor='#0d1117', activebackground=self.BG
                           ).pack(side='left', padx=8)

        def _apply():
            set_home_currency(home_var.get())
            win.destroy()
            # Rebuild the card itself (title, accent, ccy tag all switch to
            # the new home currency) — not just a numbers refresh, or the
            # box would stay labeled with the old currency.
            self._rebuild_summary_cards()
            # Re-pull FX + rebuild totals against the new pivot currency
            self._fetch_live_prices()

        tk.Button(win, text='Save', font=('Consolas', 10, 'bold'),
                  bg='#D29922', fg='#0d1117', relief='flat', padx=20, pady=6,
                  cursor='hand2', command=_apply).pack(pady=(16, 0))
        tk.Button(win, text='Cancel', font=('Consolas', 9),
                  bg='#1a2035', fg=self.DIM, relief='flat', padx=16, pady=4,
                  cursor='hand2', command=win.destroy).pack(pady=(8, 0))

    def _open_source_dialog(self, first_run: bool = False) -> bool:
        """Link a Google Sheet or import a CSV as this K-ID's portfolio source.
        Returns True if a source was saved. On first_run the dialog is modal
        and has no Cancel — the caller closes SCA if it returns False."""
        settings = load_app_settings()
        cur      = sca_get_source(settings)
        who      = CURRENT_KID or ''
        self._src_saved = False

        win = tk.Toplevel(self)
        win.title('SCA — Connect Your Portfolio' if first_run else 'SCA — Portfolio Source')
        win.configure(bg=self.BG)
        win.geometry('620x520')
        win.transient(self)
        win.grab_set()
        if first_run:
            # X on the window means "I don't want to pick" -> caller closes SCA
            win.protocol('WM_DELETE_WINDOW', win.destroy)

        tk.Label(win,
                 text='🔗  CONNECT YOUR PORTFOLIO' if first_run else '📂  PORTFOLIO SOURCE',
                 font=('Courier New', 12, 'bold'),
                 fg=self.TEAL, bg=self.BG).pack(pady=(14, 2))
        tk.Label(win, text=f'K-ID: {who or "guest (not signed in)"}',
                 font=('Courier New', 8), fg=self.DIM, bg=self.BG).pack()
        tk.Label(win,
                 text='Your ledger stays on your own sheet — nothing is uploaded anywhere.',
                 font=('Courier New', 7), fg=self.DIM, bg=self.BG).pack(pady=(2, 10))

        mode_var = tk.StringVar(value=cur.get('mode') or 'sheet')

        # ── Option 1: Google Sheet ────────────────────────────────────────────
        c1 = tk.Frame(win, bg=self.PANEL, highlightbackground=self.BORDER,
                      highlightthickness=1, padx=12, pady=10)
        c1.pack(fill='x', padx=16, pady=4)
        tk.Radiobutton(c1, text='📗  Link my Google Sheet', variable=mode_var,
                       value='sheet', font=('Courier New', 9, 'bold'),
                       bg=self.PANEL, fg=self.TEAL, selectcolor=self.PANEL,
                       activebackground=self.PANEL, activeforeground=self.TEAL,
                       relief='flat', cursor='hand2').pack(anchor='w')
        tk.Label(c1, text='Paste any Sheets URL — /edit, /pubhtml or a CSV link all work.',
                 font=('Courier New', 7), fg=self.DIM, bg=self.PANEL).pack(anchor='w')
        url_var = tk.StringVar(value=cur.get('url', '') if cur.get('mode') == 'sheet' else '')
        tk.Entry(c1, textvariable=url_var, font=('Courier New', 8), bg='#0d1117',
                 fg=self.FG, insertbackground=self.TEAL, relief='flat',
                 highlightbackground='#30363d', highlightthickness=1
                 ).pack(fill='x', pady=(6, 4), ipady=4)
        tk.Label(c1,
                 text='Sheet must be shared: File → Share → Publish to web → CSV,\n'
                      'or set link-sharing to "Anyone with the link".',
                 font=('Courier New', 7), fg=self.DIM, bg=self.PANEL,
                 justify='left').pack(anchor='w')

        # ── Option 2: CSV import ──────────────────────────────────────────────
        c2 = tk.Frame(win, bg=self.PANEL, highlightbackground=self.BORDER,
                      highlightthickness=1, padx=12, pady=10)
        c2.pack(fill='x', padx=16, pady=4)
        tk.Radiobutton(c2, text='📄  Import a CSV file', variable=mode_var,
                       value='csv', font=('Courier New', 9, 'bold'),
                       bg=self.PANEL, fg='#FFD700', selectcolor=self.PANEL,
                       activebackground=self.PANEL, activeforeground='#FFD700',
                       relief='flat', cursor='hand2').pack(anchor='w')
        tk.Label(c2, text='Offline — read straight off disk, never uploaded.',
                 font=('Courier New', 7), fg=self.DIM, bg=self.PANEL).pack(anchor='w')
        csv_var = tk.StringVar(value=cur.get('csv_path', '') if cur.get('mode') == 'csv' else '')
        row2 = tk.Frame(c2, bg=self.PANEL)
        row2.pack(fill='x', pady=(6, 0))
        tk.Entry(row2, textvariable=csv_var, font=('Courier New', 8), bg='#0d1117',
                 fg=self.FG, insertbackground=self.TEAL, relief='flat',
                 highlightbackground='#30363d', highlightthickness=1
                 ).pack(side='left', fill='x', expand=True, ipady=4)

        def _browse():
            p = filedialog.askopenfilename(
                title='Select portfolio CSV',
                filetypes=[('CSV files', '*.csv'), ('All files', '*.*')])
            if p:
                csv_var.set(p)
                mode_var.set('csv')
        tk.Button(row2, text='Browse…', command=_browse, font=('Courier New', 8),
                  bg='#1a2035', fg=self.FG2, relief='flat', padx=8,
                  cursor='hand2').pack(side='left', padx=(4, 0))

        # ── Required columns hint ─────────────────────────────────────────────
        tk.Label(win,
                 text='Required columns:  Date · Transaction Type · AssetCode · '
                      'Currency · Unit · Value · Amount',
                 font=('Courier New', 7), fg=self.DIM, bg=self.BG,
                 wraplength=560, justify='left').pack(pady=(8, 0), padx=16, anchor='w')

        status_var = tk.StringVar(value='')
        tk.Label(win, textvariable=status_var, font=('Courier New', 8),
                 fg='#FFD700', bg=self.BG, wraplength=560,
                 justify='left').pack(pady=(4, 0), padx=16, anchor='w')

        def _save_and_load():
            m = mode_var.get()
            if m == 'sheet':
                u = url_var.get().strip()
                if not u:
                    status_var.set('⚠️  Paste a Google Sheets URL first.'); return
                norm = sca_normalise_sheet_url(u)
                if 'docs.google.com' not in norm:
                    status_var.set("⚠️  That doesn't look like a Google Sheets URL."); return
                status_var.set('⏳  Testing sheet…')
                win.update_idletasks()
                try:
                    txt, _ = _mf_fetch_online_chunked(norm)
                    rows   = _mf_parse_rows(txt)
                    if not rows:
                        status_var.set('⚠️  Sheet loaded but has no transaction rows.'); return
                    v = _mf_validate_ledger(rows)
                    if not v.get('ok'):
                        status_var.set('⚠️  ' + '; '.join(v.get('errors', ['Invalid ledger'])[:2]))
                        return
                    sca_save_source(settings, who, 'sheet', url=norm,
                                    label=f'My Sheet ({len(rows)} txns)')
                except Exception as e:
                    status_var.set(f'❌  Could not read sheet:\n{type(e).__name__}: {e}')
                    return
            elif m == 'csv':
                p = csv_var.get().strip()
                if not p or not os.path.exists(p):
                    status_var.set('⚠️  Pick a CSV file that exists.'); return
                try:
                    with open(p, 'r', encoding='utf-8-sig') as f:
                        rows = _mf_parse_rows(f.read())
                    if not rows:
                        status_var.set('⚠️  CSV has no transaction rows.'); return
                    v = _mf_validate_ledger(rows)
                    if not v.get('ok'):
                        status_var.set('⚠️  ' + '; '.join(v.get('errors', ['Invalid ledger'])[:2]))
                        return
                    sca_save_source(settings, who, 'csv', csv_path=p,
                                    label=f'{os.path.basename(p)} ({len(rows)} txns)')
                except Exception as e:
                    status_var.set(f'❌  Could not read CSV: {e}'); return
            else:
                status_var.set('⚠️  Pick a Google Sheet or a CSV file.'); return

            self._src_saved = True
            self._refresh_source_label()
            win.destroy()
            if first_run:
                # First run — nothing is loaded yet, so kick off the initial load
                self._load_from_cache_then_refresh()
            else:
                messagebox.showinfo('SCA', 'Portfolio source saved. Reloading…', parent=self)
                self._refresh()

        btns = tk.Frame(win, bg=self.BG)
        btns.pack(fill='x', padx=16, pady=12)
        tk.Button(btns, text='💾  Save & Load', command=_save_and_load,
                  font=('Courier New', 10, 'bold'), bg=self.TEAL, fg='#06121f',
                  relief='flat', padx=14, pady=7, cursor='hand2'
                  ).pack(side='left', expand=True, fill='x', padx=(0, 4))
        tk.Button(btns,
                  text='Not now (close SCA)' if first_run else 'Cancel',
                  command=win.destroy,
                  font=('Courier New', 9), bg='#1a2035', fg=self.FG2,
                  relief='flat', padx=14, pady=7, cursor='hand2'
                  ).pack(side='left', expand=True, fill='x', padx=(4, 0))

        # Block until they decide, so the caller knows whether to close SCA
        self.wait_window(win)
        return self._src_saved

    def _build_error_banner(self):
        self._banner_frame = tk.Frame(self._scroll_body, bg='#1a0a0a',
                                      highlightbackground=self.RED, highlightthickness=1)
        self._banner_msg = tk.Label(self._banner_frame, text='', font=self.FONT,
                                    fg=self.RED, bg='#1a0a0a', anchor='w', wraplength=1300,
                                    justify='left')
        self._banner_msg.pack(fill='x', padx=12, pady=(6, 2))
        self._banner_sub = tk.Label(self._banner_frame, text='', font=('Courier New', 8),
                                    fg=self.FG2, bg='#1a0a0a', anchor='w', wraplength=1300)
        self._banner_sub.pack(fill='x', padx=12, pady=(0, 6))

    CCY_ACCENT = {'MYR': '#00b4d8', 'USD': '#00e676',
                  'HKD': '#ff6b6b', 'SGD': '#ffd166'}

    def _build_summary_cards(self):
        self._cards_row = tk.Frame(self._scroll_body, bg=self.BG)
        self._cards_row.pack(fill='x', padx=14, pady=(4, 6))
        self._ccy_cards = {}          # ccy -> card frame
        self._rebuild_summary_cards()
        # Back-compat aliases — older code paths still reach for these
        self._my_card = self._ccy_cards.get('MYR')
        self._us_card = self._ccy_cards.get('USD')

    def _rebuild_summary_cards(self):
        """One consolidated card in Home CCY — no more separate MYR/USD/HKD/SGD
        boxes. Every underlying currency portfolio is converted into Home CCY
        (⚙ Home CCY setting) and rolled into this single card; the Cash row
        breaks the total down by underlying currency so nothing is hidden."""
        for w in self._cards_row.winfo_children():
            w.destroy()
        self._ccy_cards = {}
        home = get_home_currency()
        self._cards_row.columnconfigure(0, weight=1)
        card = self._make_summary_card(
            self._cards_row, f'{home} POSITION',
            self.CCY_ACCENT.get(home, self.TEAL), home)
        card.grid(row=0, column=0, sticky='nsew')
        self._ccy_cards[home] = card
        self._home_card = card
        # Back-compat aliases — only meaningful if home ccy happens to be
        # MYR/USD; older code paths that reach for these now just no-op
        # gracefully when home ccy is something else.
        self._my_card = card if home == 'MYR' else None
        self._us_card = card if home == 'USD' else None

    def _make_summary_card(self, parent, title, accent, ccy):
        frame = tk.Frame(parent, bg=self.PANEL, highlightbackground=accent,
                         highlightthickness=1, padx=16, pady=12)
        title_var = tk.StringVar(value=title)
        tk.Label(frame, textvariable=title_var, font=self.FONT_B, fg=accent, bg=self.PANEL,
                 anchor='w').pack(fill='x', pady=(0, 8))
        rows = {}
        for field in ('Value', 'Cash', 'Total Inv Amt', 'Total Deposited', 'Cost', 'P/L', 'Return'):
            r = tk.Frame(frame, bg=self.PANEL)
            r.pack(fill='x', pady=1)
            tk.Label(r, text=field, font=self.FONT, fg=self.FG2, bg=self.PANEL,
                     width=10, anchor='w').pack(side='left')
            var = tk.StringVar(value=f'{ccy} 0.00' if field != 'Return' else '+0.00%')
            lbl = tk.Label(r, textvariable=var, font=self.FONT_B,
                           fg=accent if field == 'Value' else self.FG,
                           bg=self.PANEL, anchor='e')
            lbl.pack(side='right')
            rows[field] = (var, lbl)
            # Cash breakdown — one line per underlying currency, each already
            # converted into this card's ccy (home ccy), rebuilt every refresh
            # since which currencies are held can change as the ledger grows.
            if field == 'Cash':
                cash_bd = tk.Frame(frame, bg=self.PANEL)
                cash_bd.pack(fill='x', pady=(0, 2))
                frame._cash_breakdown = cash_bd
            if field == 'Total Deposited':
                dep_bd = tk.Frame(frame, bg=self.PANEL)
                dep_bd.pack(fill='x', pady=(0, 2))
                frame._dep_breakdown = dep_bd
        pos_var = tk.StringVar(value='0 positions')
        tk.Label(frame, textvariable=pos_var, font=self.FONT,
                 fg=self.DIM, bg=self.PANEL, anchor='w').pack(fill='x', pady=(6, 0))
        frame._rows = rows
        frame._pos_var = pos_var
        frame._ccy = ccy
        frame._title_var = title_var
        return frame

    def _build_tabs(self):
        tab_row = tk.Frame(self._scroll_body, bg=self.BG)
        tab_row.pack(fill='x', padx=14, pady=(0, 4))
        self._tab_btns = {}
        # Driven by MARKET_SPEC (not hardcoded to MYR/USD) so a HKD or SGD
        # portfolio — or any future market registered there — gets its own
        # filter tab instead of being stuck lumped into 'ALL' with no way
        # to view it on its own.
        tab_options = [('⊕ ALL', 'ALL')] + [
            (spec['label'], spec['market']) for spec in MARKET_SPEC.values()
        ]
        for label, val in tab_options:
            btn = tk.Radiobutton(tab_row, text=label, variable=self._tab_var, value=val,
                                  command=self._on_tab_change,
                                  font=self.FONT_B, relief='flat', cursor='hand2',
                                  bg=self.PANEL, fg=self.FG,
                                  selectcolor=self.TEAL, activebackground=self.PANEL,
                                  activeforeground=self.TEAL,
                                  indicatoron=False, padx=14, pady=6)
            btn.pack(side='left', padx=(0, 4))
            self._tab_btns[val] = btn

        # ── Composition pie toggle ────────────────────────────────────────────
        self._pie_open = tk.BooleanVar(value=False)
        self._pie_btn = tk.Button(
            tab_row, text='🥧  Composition', font=self.FONT_B,
            bg=self.PANEL, fg=self.GOLD,
            relief='flat', cursor='hand2', padx=14, pady=6,
            command=self._toggle_pie)
        self._pie_btn.pack(side='left', padx=(10, 0))

        # Panel lives directly under the row, collapsed by default
        self._pie_panel = tk.Frame(self._scroll_body, bg=self.BG)
        self._pie_canvas = None

        # ── Portfolio View toggle ──────────────────────────────────────────
        # Combines: allocation by region + by portfolio (ledger), a
        # forced-single-currency summary, and a returns table with 3 modes
        # (% return / native gain-loss / forced-ccy).
        self._portview_open = tk.BooleanVar(value=False)
        self._portview_btn = tk.Button(
            tab_row, text='📊  Portfolio View', font=self.FONT_B,
            bg=self.PANEL, fg=self.GOLD,
            relief='flat', cursor='hand2', padx=14, pady=6,
            command=self._toggle_portview)
        self._portview_btn.pack(side='left', padx=(10, 0))

        self._portview_panel = tk.Frame(self._scroll_body, bg=self.BG)
        self._portview_forced_ccy_var = tk.StringVar(value='')
        self._portview_mode_var       = tk.StringVar(value='PCT')  # PCT / GAINLOSS / FORCED

    def _toggle_portview(self):
        """Show/hide the Portfolio View panel. Built lazily, same pattern as
        the Composition pie — no cost until someone actually opens it."""
        opening = not self._portview_open.get()
        self._portview_open.set(opening)
        if opening:
            anchor = getattr(self, '_holdings_anchor', None)
            if anchor is not None and anchor.winfo_exists():
                self._portview_panel.pack(fill='x', padx=14, pady=(0, 6), before=anchor)
            else:
                self._portview_panel.pack(fill='x', padx=14, pady=(0, 6))
            self._portview_btn.configure(text='📊  Portfolio View  ▲')
            self._draw_portview()
        else:
            self._portview_panel.pack_forget()
            self._portview_btn.configure(text='📊  Portfolio View')

    def _portview_collect(self):
        """One row per priced holding, in native currency plus converted into
        a single forced base currency. Mirrors the same currency-forcing rule
        the value chart/pie already use: majority currency wins unless the
        user has picked one explicitly via the Summary dropdown."""
        portfolios = self._portfolios or {}
        price_data = self._last_price_data or {}
        fx         = self._fx_rates or {getattr(self, '_fx_home', get_home_currency()): 1.0}

        ccy_counts = {}
        for port in portfolios.values():
            c = port.get('base_currency', 'USD')
            ccy_counts[c] = ccy_counts.get(c, 0) + 1
        majority = get_home_currency() if ccy_counts else 'MYR'
        base_ccy = self._portview_forced_ccy_var.get() or majority

        def _to_base(amount, ccy):
            if ccy == base_ccy:
                return amount
            # Pivot is whichever currency fx[] is keyed against (home
            # currency) — works regardless of what that home currency is,
            # not just when it happens to be MYR.
            amount_pivot = amount * fx.get(ccy, 1.0)
            return amount_pivot / fx.get(base_ccy, 1.0)

        rows = []
        for pk, port in portfolios.items():
            ccy    = port.get('base_currency', 'USD')
            market = MARKET_SPEC.get(ccy, {}).get('market', 'US')
            label  = MARKET_SPEC.get(ccy, {}).get('label', ccy)
            for ticker, item in port.get('holdings', {}).items():
                if item.get('_is_cash'):
                    continue
                shares, cost_v = item.get('shares', 0), item.get('cost_value', 0)
                price = price_data.get(ticker)
                if not price or shares <= 0:
                    continue
                mv_native = shares * price
                pl_native = mv_native - cost_v
                pl_pct    = (pl_native / cost_v * 100) if cost_v else None
                rows.append({
                    'ticker': ticker, 'port_key': pk, 'port_label': label,
                    'region': market, 'ccy': ccy,
                    'mv_native': mv_native, 'cost_native': cost_v,
                    'pl_native': pl_native, 'pl_pct': pl_pct,
                    'mv_base':   _to_base(mv_native, ccy),
                    'cost_base': _to_base(cost_v, ccy),
                    'pl_base':   _to_base(pl_native, ccy),
                })
        return rows, base_ccy, sorted(ccy_counts.keys())

    def _draw_portview(self):
        """Rebuild the whole Portfolio View panel: summary, region/portfolio
        allocation, and the 3-mode returns table."""
        if not self._portview_open.get():
            return
        for w in self._portview_panel.winfo_children():
            w.destroy()

        rows, base_ccy, avail_ccys = self._portview_collect()
        if not rows:
            tk.Label(self._portview_panel, text='No priced holdings to summarize yet.',
                     font=self.FONT, fg=self.DIM, bg=self.BG).pack(pady=10)
            return

        container = tk.Frame(self._portview_panel, bg=self.PANEL,
                             highlightbackground=self.BORDER, highlightthickness=1)
        container.pack(fill='x')

        tk.Label(container, text='PORTFOLIO VIEW', font=self.FONT_B, fg=self.GOLD,
                 bg=self.PANEL, anchor='w', padx=12, pady=(8, 2)).pack(fill='x')

        self._portview_build_summary(container, rows, base_ccy, avail_ccys)
        self._portview_build_allocation(container, rows, 'region',     'By region')
        self._portview_build_allocation(container, rows, 'port_label', 'By portfolio (ledger)')
        self._portview_build_returns(container, rows, base_ccy)

    def _portview_build_summary(self, parent, rows, base_ccy, avail_ccys):
        """Summary mode — everything forced into ONE currency, selectable."""
        sfx          = ccy_symbol(base_ccy)
        total_mv     = sum(r['mv_base']   for r in rows)
        total_cost   = sum(r['cost_base'] for r in rows)
        total_pl     = total_mv - total_cost
        total_pl_pct = (total_pl / total_cost * 100) if total_cost else 0.0

        row = tk.Frame(parent, bg=self.PANEL)
        row.pack(fill='x', padx=12, pady=(2, 6))
        tk.Label(row, text='Summary  ·  forced ccy:', font=self.FONT, fg=self.FG2,
                 bg=self.PANEL).pack(side='left')

        ccy_opts = list(avail_ccys) or ['MYR']
        if base_ccy not in ccy_opts:
            ccy_opts = ccy_opts + [base_ccy]
        if not self._portview_forced_ccy_var.get():
            self._portview_forced_ccy_var.set(base_ccy)
        om = tk.OptionMenu(row, self._portview_forced_ccy_var, *ccy_opts,
                           command=lambda _v: self._draw_portview())
        om.configure(font=self.FONT_B, bg=self.PANEL, fg=self.TEAL, relief='flat',
                     highlightthickness=0, activebackground=self.PANEL)
        om.pack(side='left', padx=(4, 0))

        cards = tk.Frame(parent, bg=self.PANEL)
        cards.pack(fill='x', padx=12, pady=(0, 8))
        color = self.GREEN if total_pl >= 0 else self.RED
        for text, val, clr in (
            ('Total value', f'{sfx}{total_mv:,.2f}',   self.FG),
            ('Total cost',  f'{sfx}{total_cost:,.2f}', self.FG2),
            ('Gain / loss', f'{sfx}{total_pl:+,.2f}',  color),
            ('Return %',    f'{total_pl_pct:+.2f}%',   color),
        ):
            c = tk.Frame(cards, bg=self.BG, highlightbackground=self.BORDER,
                        highlightthickness=1, padx=10, pady=6)
            c.pack(side='left', fill='x', expand=True, padx=(0, 6))
            tk.Label(c, text=text, font=('Courier New', 7), fg=self.DIM, bg=self.BG,
                     anchor='w').pack(fill='x')
            tk.Label(c, text=val, font=self.FONT_B, fg=clr, bg=self.BG,
                     anchor='w').pack(fill='x')

    def _portview_build_allocation(self, parent, rows, group_key, title):
        """Allocation breakdown bar — by region (market) or by portfolio
        (the code recorded per-row in the ledger), both in forced ccy."""
        grouped = {}
        for r in rows:
            grouped[r[group_key]] = grouped.get(r[group_key], 0.0) + r['mv_base']
        total = sum(grouped.values())
        if not total:
            return
        tk.Label(parent, text=title, font=self.FONT, fg=self.FG2, bg=self.PANEL,
                 anchor='w', padx=12, pady=(4, 2)).pack(fill='x')
        bar_wrap = tk.Frame(parent, bg=self.PANEL)
        bar_wrap.pack(fill='x', padx=12, pady=(0, 4))
        palette   = ['#00b4d8', '#00e676', '#ffd166', '#ff6b6b', '#a78bfa', '#4a90d9']
        bar_outer = tk.Frame(bar_wrap, bg='#1a2035', height=18)
        bar_outer.pack(fill='x')
        bar_outer.pack_propagate(False)
        legend = tk.Frame(bar_wrap, bg=self.PANEL)
        legend.pack(fill='x', pady=(3, 0))
        for i, (name, val) in enumerate(sorted(grouped.items(), key=lambda x: -x[1])):
            pct   = val / total
            color = palette[i % len(palette)]
            seg = tk.Frame(bar_outer, bg=color, width=max(1, int(pct * 900)), height=18)
            seg.pack(side='left', fill='y')
            tk.Label(legend, text=f'● {name}  {pct*100:.1f}%', font=('Courier New', 7),
                     fg=color, bg=self.PANEL).pack(side='left', padx=(0, 10))

    def _portview_build_returns(self, parent, rows, base_ccy):
        """Returns table — 3 display modes:
          PCT      → % return only
          GAINLOSS → gain/loss in the holding's own (native) currency + %
          FORCED   → value & gain/loss converted into the forced base ccy
        """
        hdr = tk.Frame(parent, bg=self.PANEL)
        hdr.pack(fill='x', padx=12, pady=(6, 2))
        tk.Label(hdr, text='Returns', font=self.FONT, fg=self.FG2, bg=self.PANEL).pack(side='left')

        for label, val in (('% Return', 'PCT'), ('Gain / Loss', 'GAINLOSS'), ('Forced ccy', 'FORCED')):
            active = self._portview_mode_var.get() == val
            tk.Radiobutton(hdr, text=label, variable=self._portview_mode_var, value=val,
                          command=self._draw_portview, font=self.FONT_B, relief='flat',
                          cursor='hand2', bg=self.TEAL if active else self.PANEL,
                          fg='#000' if active else self.FG2, selectcolor=self.TEAL,
                          activebackground=self.PANEL, activeforeground=self.TEAL,
                          indicatoron=False, padx=8, pady=2).pack(side='right', padx=2)

        mode = self._portview_mode_var.get()
        tree_wrap = tk.Frame(parent, bg=self.PANEL)
        tree_wrap.pack(fill='x', padx=12, pady=(2, 10))

        if mode == 'PCT':
            cols = ('TICKER', 'PORTFOLIO', '% RETURN')
        elif mode == 'GAINLOSS':
            cols = ('TICKER', 'PORTFOLIO', 'CCY', 'GAIN/LOSS', '% RETURN')
        else:
            cols = ('TICKER', 'PORTFOLIO', f'VALUE ({base_ccy})', f'GAIN/LOSS ({base_ccy})')

        tv = ttk.Treeview(tree_wrap, columns=cols, show='headings',
                          height=min(10, max(3, len(rows))))
        for c in cols:
            tv.column(c, width=130, anchor='w' if c in ('TICKER', 'PORTFOLIO') else 'e',
                      stretch=True)
            tv.heading(c, text=c)
        tv.configure(style='SCA.Treeview')
        tv.tag_configure('gain', foreground=self.GREEN)
        tv.tag_configure('loss', foreground=self.RED)
        tv.pack(fill='x')

        for r in sorted(rows, key=lambda r: -(r['pl_pct'] or 0)):
            tag = 'gain' if (r['pl_pct'] or 0) >= 0 else 'loss'
            if mode == 'PCT':
                tv.insert('', 'end', tags=(tag,), values=(
                    r['ticker'], r['port_label'],
                    f"{r['pl_pct']:+.2f}%" if r['pl_pct'] is not None else '—'))
            elif mode == 'GAINLOSS':
                sfx = ccy_symbol(r['ccy'])
                tv.insert('', 'end', tags=(tag,), values=(
                    r['ticker'], r['port_label'], r['ccy'],
                    f"{sfx}{r['pl_native']:+,.2f}",
                    f"{r['pl_pct']:+.2f}%" if r['pl_pct'] is not None else '—'))
            else:
                sfx = ccy_symbol(base_ccy)
                tv.insert('', 'end', tags=(tag,), values=(
                    r['ticker'], r['port_label'],
                    f"{sfx}{r['mv_base']:,.2f}", f"{sfx}{r['pl_base']:+,.2f}"))

    def _toggle_pie(self):
        """Show/hide the composition pie. Built lazily — a matplotlib canvas
        that nobody opens is pure startup cost."""
        opening = not self._pie_open.get()
        self._pie_open.set(opening)
        if opening:
            anchor = getattr(self, '_holdings_anchor', None)
            if anchor is not None and anchor.winfo_exists():
                self._pie_panel.pack(fill='x', padx=14, pady=(0, 6), before=anchor)
            else:
                self._pie_panel.pack(fill='x', padx=14, pady=(0, 6))
            self._pie_btn.configure(text='🥧  Composition  ▲')
            self._draw_pie()
        else:
            self._pie_panel.pack_forget()
            self._pie_btn.configure(text='🥧  Composition')

    def _draw_pie(self):
        """Pie of current holdings by market value, honouring the active tab.
        USD holdings are converted to MYR so one pie can show both sides —
        adding a $ slice to an RM slice would otherwise be meaningless."""
        if not self._pie_open.get():
            return
        try:
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        except Exception:
            return

        for w in self._pie_panel.winfo_children():
            w.destroy()
        self._pie_canvas = None

        tab   = self._tab_var.get()
        rows  = []          # (ticker, myr_value)
        for pk, port in (self._portfolios or {}).items():
            ccy = _port_ccy(pk)
            mkt = MARKET_SPEC.get(ccy, {}).get('market', 'US')
            if tab != 'ALL' and tab != mkt:
                continue
            fx = (self._fx_rates or {}).get(ccy)
            if not fx:
                continue                # no rate -> can't mix into a MYR pie
            for tkr, item in port.get('holdings', {}).items():
                if item.get('_is_cash'):
                    continue
                sh = item.get('shares', 0)
                if sh <= 0:
                    continue
                px = (self._last_price_data or {}).get(tkr)
                if not px:
                    continue
                short = tkr
                for _suf in ('.KL', '.HK', '.SI'):
                    short = short.replace(_suf, '')
                rows.append((short, sh * px * fx))

        if not rows:
            tk.Label(self._pie_panel,
                     text='No priced holdings to chart yet.',
                     font=self.FONT, fg=self.DIM, bg=self.BG).pack(pady=10)
            return

        rows.sort(key=lambda r: -r[1])
        total = sum(v for _, v in rows)

        # Long tails make an unreadable pie — keep the top 12, group the rest.
        TOP = 12
        if len(rows) > TOP:
            head, tail = rows[:TOP], rows[TOP:]
            head.append((f'Others ({len(tail)})', sum(v for _, v in tail)))
            rows = head

        labels = [f'{t}  {v/total*100:.2f}%' for t, v in rows]
        vals   = [v for _, v in rows]

        fig = Figure(figsize=(7.2, 3.0), dpi=100, facecolor=self.BG)
        ax  = fig.add_subplot(111)
        ax.set_facecolor(self.BG)
        try:
            import matplotlib.cm as cm
            import numpy as _np
            colors = cm.get_cmap('tab20')(_np.linspace(0, 1, len(vals)))
        except Exception:
            colors = None

        wedges, _ = ax.pie(vals, startangle=90, colors=colors,
                           wedgeprops=dict(width=0.42, edgecolor=self.BG,
                                           linewidth=1.2))
        ax.axis('equal')

        _c = _MARKET_TO_CCY.get(tab)
        ccy_note = ('MYR' if _c == 'MYR' else
                    f'{_c}→MYR' if _c else 'MYR (all converted)')
        ax.text(0, 0.06, f'RM{total:,.2f}', ha='center', va='center',
                fontsize=12, fontweight='bold', color=self.FG)
        ax.text(0, -0.14, f'{len(rows)} slices · {ccy_note}', ha='center',
                va='center', fontsize=7, color=self.DIM)

        ax.legend(wedges, labels, loc='center left',
                  bbox_to_anchor=(0.98, 0.5), fontsize=6.5, ncol=2,
                  frameon=False, labelcolor=self.FG2)
        fig.subplots_adjust(left=0.02, right=0.58, top=0.98, bottom=0.02)

        self._pie_canvas = FigureCanvasTkAgg(fig, master=self._pie_panel)
        self._pie_canvas.draw()
        self._pie_canvas.get_tk_widget().pack(fill='x')

    _SORT_ARROWS = {None: '', False: '  ▲', True: '  ▼'}

    @staticmethod
    def _sort_key(val: str):
        """Turn a displayed cell back into something sortable.

        Cells are pre-formatted strings ('RM0.7403', '+1.30%', '18.53%', '—'),
        so a plain string sort puts RM10 before RM9 and '-5%' next to '-0.1%'.
        Strip the decoration and sort on the number underneath; anything that
        isn't numeric falls back to case-insensitive text.
        """
        s = (val or '').strip()
        if s in ('—', '', '…'):
            return (2, 0.0, '')          # blanks always sort last
        cleaned = (s.replace('RM', '').replace('$', '')
                    .replace('%', '').replace(',', '').replace('+', '').strip())
        try:
            return (0, float(cleaned), '')
        except ValueError:
            return (1, 0.0, s.lower())

    def _sort_holdings(self, col: str):
        """Sort the holdings table by a column. Click again to flip direction."""
        if self._sort_col == col:
            self._sort_desc = not self._sort_desc
        else:
            self._sort_col  = col
            # Numbers are most useful biggest-first; text reads better A→Z.
            self._sort_desc = col not in ('TICKER', 'PORTFOLIO', 'CCY')

        idx  = self._hold_tree['columns'].index(col)
        rows = [(self._hold_tree.set(k, col), k)
                for k in self._hold_tree.get_children('')]
        rows.sort(key=lambda r: self._sort_key(r[0]), reverse=self._sort_desc)
        for pos, (_, k) in enumerate(rows):
            self._hold_tree.move(k, '', pos)

        # Arrow on the active column only
        for c in self._hold_tree['columns']:
            self._hold_tree.heading(
                c, text=c + (self._SORT_ARROWS[self._sort_desc] if c == col else ''))

    def _reapply_sort(self):
        """Re-sort after a data refresh so the chosen order survives."""
        if self._sort_col:
            col, desc = self._sort_col, self._sort_desc
            self._sort_col = None          # force _sort_holdings to keep `desc`
            self._sort_desc = not desc
            self._sort_holdings(col)

    def _update_hold_columns(self):
        """Show/hide the PORTFOLIO and CCY columns depending on what Source
        actually loaded — a ledger that only ever holds one currency (the
        common case: a plain single-market Google Sheet or CSV) doesn't need
        a PORTFOLIO or CCY column repeating the same value on every row.
        Both reappear automatically the moment a second currency/portfolio
        shows up (e.g. the user links a second market), no settings toggle
        needed — it just reflects what's actually in the ledger."""
        portfolios = self._portfolios or {}
        active = [p for p in portfolios.values() if p.get('holdings')]
        ccys = {p.get('base_currency', 'USD') for p in active}
        show_portfolio = len(active) > 1
        show_ccy       = len(ccys) > 1
        cols = self._hold_tree['columns']
        display = [c for c in cols
                   if (c != 'PORTFOLIO' or show_portfolio)
                   and (c != 'CCY' or show_ccy)]
        self._hold_tree['displaycolumns'] = display

    def _build_holdings_table(self):
        # Anchor so the pie panel can be inserted directly above this block
        self._holdings_anchor = tk.Frame(self._scroll_body, bg=self.BG, height=0)
        self._holdings_anchor.pack(fill='x')
        hdr = tk.Frame(self._scroll_body, bg=self.BG)
        hdr.pack(fill='x', padx=14)
        tk.Label(hdr, text='HOLDINGS', font=self.FONT_B, fg=self.FG2, bg=self.BG,
                 anchor='w').pack(side='left')
        self._pos_total_var = tk.StringVar(value='0 positions')
        tk.Label(hdr, textvariable=self._pos_total_var, font=self.FONT,
                 fg=self.DIM, bg=self.BG, anchor='e').pack(side='right')
        tk.Button(hdr, text='📒 Holdings Report', font=('Courier New', 8, 'bold'),
                  bg='#1a2035', fg=self.TEAL, relief='flat', bd=0, padx=8,
                  command=self._open_holdings_report_popup).pack(side='right', padx=(0, 10))
        tk.Button(hdr, text='💵 Dividend Log', font=('Courier New', 8, 'bold'),
                  bg='#1a2035', fg=self.GREEN, relief='flat', bd=0, padx=8,
                  command=self._open_dividend_log_popup).pack(side='right', padx=(0, 10))

        frame = tk.Frame(self._scroll_body, bg=self.BG)
        frame.pack(fill='both', expand=True, padx=14, pady=(2, 0))

        cols = ('TICKER','PORTFOLIO','CCY','QTY','AVG COST','LIVE PRICE',
                'DAY Δ','VALUE','P/L','P/L %','WEIGHT','1Y TREND')
        self._hold_tree = ttk.Treeview(frame, columns=cols, show='headings', height=12)
        cw = {'TICKER':88,'PORTFOLIO':110,'CCY':50,'QTY':80,'AVG COST':90,
              'LIVE PRICE':90,'DAY Δ':80,'VALUE':110,'P/L':100,'P/L %':70,
              'WEIGHT':70,'1Y TREND':80}
        for col in cols:
            self._hold_tree.heading(
                col, text=col,
                command=lambda c=col: self._sort_holdings(c))
            self._hold_tree.column(col, width=cw.get(col, 80),
                                   anchor='w' if col in ('TICKER','PORTFOLIO') else 'e',
                                   stretch=False)
        self._sort_col     = None
        self._sort_desc    = False

        sty = ttk.Style(self)
        sty.configure('SCA.Treeview', background=self.PANEL, fieldbackground=self.PANEL,
                       foreground=self.FG, rowheight=24, font=self.FONT)
        sty.configure('SCA.Treeview.Heading', background=self.BG, foreground=self.DIM,
                       font=('Courier New', 8, 'bold'), relief='flat')
        sty.map('SCA.Treeview', background=[('selected', '#1a2a3a')])
        self._hold_tree.configure(style='SCA.Treeview')

        vsb = ttk.Scrollbar(frame, orient='vertical', command=self._hold_tree.yview)
        hsb = ttk.Scrollbar(frame, orient='horizontal', command=self._hold_tree.xview)
        self._hold_tree.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)
        self._hold_tree.grid(row=0, column=0, sticky='nsew')
        vsb.grid(row=0, column=1, sticky='ns')
        hsb.grid(row=1, column=0, sticky='ew')
        frame.rowconfigure(0, weight=1); frame.columnconfigure(0, weight=1)

        self._hold_tree.tag_configure('gain',    foreground=self.GREEN)
        self._hold_tree.tag_configure('loss',    foreground=self.RED)
        self._hold_tree.tag_configure('neutral', foreground=self.FG)
        self._hold_tree.tag_configure('my',      foreground=self.TEAL)
        self._hold_tree.tag_configure('us',      foreground=self.GREEN)

        self._hold_tree.bind('<ButtonRelease-1>', self._on_row_click)
        self._selected_ticker = None

    def _refresh_today_activity(self):
        """Populate Today's Activity from raw NEWPOR rows.
        Shows every Buy and Sell transacted today with ticker, units, price, amount.
        """
        import datetime as _dt
        today = _dt.date.today()
        # Google Sheets CSV exports dates WITHOUT leading zeros: 7/13/2026 not 07/13/2026
        # Cover all realistic format variants so nothing slips through
        today_fmts = {
            today.strftime('%m/%d/%Y'),                          # 07/13/2026
            f'{today.month}/{today.day}/{today.year}',           # 7/13/2026 (no leading zeros)
            today.strftime('%d/%m/%Y'),                          # 13/07/2026
            f'{today.day}/{today.month}/{today.year}',           # 13/7/2026
            today.strftime('%Y-%m-%d'),                          # 2026-07-13
            today.strftime('%m-%d-%Y'),                          # 07-13-2026
        }

        if not hasattr(self, '_act_buy_frame'):
            return

        raw_rows = getattr(self, '_rows', None) or []

        buys  = []
        sells = []

        for row in raw_rows:
            date_s = row.get(_NC_DATE, '').strip()
            if not date_s:
                continue
            # Fast check against known format strings first
            if date_s not in today_fmts:
                # Slow fallback: try parsing and compare date object
                matched = False
                for fmt in ('%m/%d/%Y', '%d/%m/%Y', '%Y-%m-%d', '%m-%d-%Y', '%d-%m-%Y'):
                    try:
                        if _dt.datetime.strptime(date_s, fmt).date() == today:
                            matched = True
                            today_fmts.add(date_s)   # cache for remaining rows
                            break
                    except ValueError:
                        continue
                if not matched:
                    continue
            ttype  = row.get(_NC_TYPE,   '').strip().lower()
            asset  = row.get(_NC_ASSET,  '').strip()
            ccy    = row.get(_NC_CCY,    '').strip().upper()
            unit   = _mf_strip_currency(row.get(_NC_UNIT,   '0'))
            price  = _mf_strip_currency(row.get(_NC_VALUE,  '0'))
            amount = _mf_strip_currency(row.get(_NC_AMOUNT, '0'))
            prefix = ccy_symbol(ccy)

            if ttype in ('buy',):
                buys.append((asset, unit, price, amount, prefix))
            elif ttype in ('sell',):
                sells.append((asset, unit, price, amount, prefix))

        # Clear and rebuild buy panel
        for w in self._act_buy_frame.winfo_children():
            w.destroy()
        if buys:
            total_in = 0.0
            pfx0 = buys[0][4]
            for asset, unit, price, amount, pfx in buys:
                r = tk.Frame(self._act_buy_frame, bg='#0a1a0a')
                r.pack(fill='x', pady=1)
                tk.Label(r, text=asset, font=('Courier New', 8, 'bold'),
                         fg='#3FB950', bg='#0a1a0a', width=12, anchor='w').pack(side='left')
                qty_str = _fmt_units(abs(unit)) if pfx == 'RM' else f'{abs(unit):,.4f}'
                tk.Label(r, text=f'{qty_str} u @ {pfx}{price:,.4f}',
                         font=('Courier New', 7), fg=self.FG2,
                         bg='#0a1a0a').pack(side='left', padx=4)
                tk.Label(r, text=f'{pfx}{abs(amount):,.2f}',
                         font=('Courier New', 8, 'bold'),
                         fg='#3FB950', bg='#0a1a0a', anchor='e').pack(side='right')
                total_in += abs(amount)
            self._act_buy_total.configure(
                text=f'Total in:  {pfx0}{total_in:,.2f}  ({len(buys)} trade{"s" if len(buys)!=1 else ""})')
        else:
            tk.Label(self._act_buy_frame, text='No buys today',
                     font=('Courier New', 8), fg=self.DIM,
                     bg='#0a1a0a').pack(anchor='w')
            self._act_buy_total.configure(text='')

        # Clear and rebuild sell panel
        for w in self._act_sell_frame.winfo_children():
            w.destroy()
        if sells:
            total_out = 0.0
            pfx0 = sells[0][4]
            for asset, unit, price, amount, pfx in sells:
                r = tk.Frame(self._act_sell_frame, bg='#1a0a0a')
                r.pack(fill='x', pady=1)
                tk.Label(r, text=asset, font=('Courier New', 8, 'bold'),
                         fg='#F85149', bg='#1a0a0a', width=12, anchor='w').pack(side='left')
                qty_str = _fmt_units(abs(unit)) if pfx == 'RM' else f'{abs(unit):,.4f}'
                tk.Label(r, text=f'{qty_str} u @ {pfx}{price:,.4f}',
                         font=('Courier New', 7), fg=self.FG2,
                         bg='#1a0a0a').pack(side='left', padx=4)
                tk.Label(r, text=f'{pfx}{abs(amount):,.2f}',
                         font=('Courier New', 8, 'bold'),
                         fg='#F85149', bg='#1a0a0a', anchor='e').pack(side='right')
                total_out += abs(amount)
            self._act_sell_total.configure(
                text=f'Total out: {pfx0}{total_out:,.2f}  ({len(sells)} trade{"s" if len(sells)!=1 else ""})')
        else:
            tk.Label(self._act_sell_frame, text='No sells today',
                     font=('Courier New', 8), fg=self.DIM,
                     bg='#1a0a0a').pack(anchor='w')
            self._act_sell_total.configure(text='')

